window.AponarQuartet2Data={"q2":{"chapters.theme_bn":{"প্রসঙ্গ, পরোক্ষ কথা ও ভাষার সূক্ষ্ম পার্থক্য":"സന്ദർഭം, പരോക്ഷ സംസാരം, ഭാഷയുടെ സൂക്ഷ്മ വ്യത്യാസങ്ങൾ","যুক্তি, বিকল্প দৃষ্টিকোণ ও মতামত গঠন":"യുക്തി, ബദൽ വീക്ഷണം, അഭിപ്രായ രൂപീകരണം","অভিজ্ঞতা থেকে শেখা ও ভদ্রভাবে মতের পার্থক্য বলা":"അനുഭവത്തിൽ നിന്ന് പഠിക്കലും മാന്യമായി അഭിപ്രായ വ്യത്യാസം പറയലും","কাজের মূল্যবোধ, সাক্ষাৎকার নেওয়া ও তথ্য সাজানো":"ജോലി മൂല്യങ്ങൾ, അഭിമുഖം നടത്തൽ, വിവരങ്ങൾ ക്രമീകരിക്കൽ","ঘটনার মোড়, উপমা ও অনুভূতির পরিবর্তন পড়া":"സംഭവങ്ങളുടെ വഴിത്തിരിവ്, ഉപമകൾ, വികാര മാറ്റങ്ങൾ എന്നിവ വായിക്കൽ","তুলনা, পরিবর্তনের প্রবণতা ও সীমিত সিদ্ধান্ত":"താരതമ്യം, മാറ്റത്തിന്റെ പ്രവണത, പരിമിതമായ തീരുമാനം"},"chapters.title_bn":{"অধ্যায় ৮ · পেশাদারিত্ব ও সাক্ষাৎকার":"അധ്യായം 8 · പ്രൊഫഷണലിസവും അഭിമുഖങ്ങളും","অধ্যায় ১০ · তথ্য দিয়ে সমাজ বোঝা":"അധ്യായം 10 · ഡാറ്റയിലൂടെ സമൂഹത്തെ മനസ്സിലാക്കൽ","অধ্যায় ৯ · গল্প, অনুভূতি ও পর্যালোচনা":"അധ്യായം 9 · കഥകൾ, വികാരങ്ങൾ, അവലോകനങ്ങൾ","অধ্যায় ১২ · চিন্তার পরিবর্তন ও সমাজ":"അധ്യായം 12 · മാറുന്ന ചിന്തകളും സമൂഹവും","অধ্যায় ১১ · শব্দের আড়ালের অর্থ":"അധ്യായം 11 · വാക്കുകൾക്ക് പിന്നിലെ മറഞ്ഞ അർത്ഥങ്ങൾ","অধ্যায় ৭ · ভিন্ন সংস্কৃতি, নতুন উপলব্ধি":"അധ്യായം 7 · വ്യത്യസ്ത സംസ്കാരങ്ങൾ, പുതിയ തിരിച്ചറിവുകൾ"},"form_guide.label":{"সম্ভাব্য রূপ":"സാധ്യതാ രൂപം (potential form)","い-বিশেষণ":"い-വിശേഷണം","な-বিশেষণ":"な-വിശേഷണം","ইচ্ছার রূপ":"ഇച്ഛാ രൂപം (volitional form)"},"form_guide.meaning_bn":{"বর্তমান বা ভবিষ্যতের সাধারণ নেতিবাচক রূপ।":"വർത്തമാനത്തിന്റെയോ ഭാവിയുടെയോ പൊതുവായ നിഷേധ രൂപം.","ます・です ছাড়া সাধারণ রূপ: বর্তমান, অতীত, ইতিবাচক ও নেতিবাচক। N ও な-বিশেষণের だ কখন বাদ/な/の হবে তা প্রতিটি নিয়মে দেওয়া আছে।":"ます/です അല്ലാത്ത സാധാരണ രൂപങ്ങൾ: വർത്തമാനം, ഭൂതം, അസ്തിവാചകം, നിഷേധം. നാമങ്ങൾക്കും な-വിശേഷണങ്ങൾക്കും だ എപ്പോൾ ഒഴിവാക്കണം അല്ലെങ്കിൽ な/の എപ്പോൾ ഉപയോഗിക്കണം എന്നത് ഓരോ നിയമത്തിലും വിശദീകരിച്ചിരിക്കുന്നു.","বিশেষ্যকে বর্ণনা করলে な লাগে। সব গঠনে な থাকবে না; পাঠের সংযোগ দেখুন।":"ഒരു നാമത്തെ വിവരിക്കുമ്പോൾ な ആവശ്യമാണ്. な എല്ലാ ഘടനകളിലും ഉണ്ടാകില്ല; പാഠത്തിലെ ബന്ധങ്ങൾ പരിശോധിക്കുക.","সাধারণ অতীত রূপ।":"പൊതുവായ ഭൂതകാല രൂപം.","ます-রূপ থেকে শুধু ます বাদ দিন।":"ます-രൂപത്തിൽ നിന്ന് ます ഒഴിവാക്കിയാൽ മതി.","“করি/করব” ধরনের volitional form।":"\"ചെയ്യും/ചെയ്യാം\" തരത്തിലുള്ള volitional form.","ক্রিয়ার সংযোগের て-form; কোথাও で হয়।":"ക്രിയാ രൂപമാറ്റത്തിന്റെ て-form; ചിലപ്പോൾ അത് で ആയി മാറും.","কোনো কাজ করতে পারা বোঝায়।":"എന്തെങ്കിലും ചെയ്യാൻ കഴിയുന്നതിനെ സൂചിപ്പിക്കുന്നു.","বিশেষ্য: ব্যক্তি, বস্তু বা বিষয়ের নাম।":"നാമം: ഒരു വ്യക്തിയുടെയോ വസ്തുവിന്റെയോ വിഷയത്തിന്റെയോ പേര്.","い-বিশেষণ, যেমন বড়, দামি। নেতিবাচক ও অতীতে রূপ বদলায়।":"വലുത്, വിലയേറിയത് പോലുള്ള い-വിശേഷണം. നിഷേധത്തിലും ഭൂതകാലത്തിലും രൂപം മാറും.","ক্রিয়ার dictionary form; এর মানে সব ক্রিয়া る দিয়ে শেষ হবে না।":"ക്രിയകളുടെ dictionary form; എല്ലാ ക്രിയകളും る-ൽ അവസാനിക്കുമെന്ന് ഇതിനർത്ഥമില്ല.","শর্তের ば-form।":"ഷർത്ത് ば-form."},"lessons.examples.bangla":{"সংস্কৃতি আলাদা বলেই আলোচনা করা জরুরি।":"സംസ്കാരങ്ങൾ വ്യത്യസ്തമായതുകൊണ്ട് തന്നെ ചർച്ച ആവശ്യമാണ്.","তিনি শিক্ষক বলার চেয়ে বরং বন্ধুর মতো।":"അദ്ദേഹം അധ്യാപകനാണെന്ന് പറയുന്നതിനേക്കാൾ, അദ്ദേഹം ഒരു സുഹൃത്തിനെപ്പോലെയാണ്.","আগামীকাল হলে সাহায্য করা একেবারে অসম্ভব নয়।":"നാളെയാണെങ്കിൽ, സഹായിക്കുന്നത് പൂർണ്ണമായും അസാധ്യമല്ല.","বয়স বাড়ার সঙ্গে চিন্তার ধরনও বদলায়।":"പ്രായം കൂടുന്നതിനനുസരിച്ച് ചിന്താരീതിയും മാറുന്നു.","শিশুটি কাঁদল মনে হতেই সঙ্গে সঙ্গে হাসল।":"കുട്ടി കരയുകയാണെന്ന് തോന്നിയ നിമിഷം തന്നെ അവർ ഉടൻ ചിരിച്ചു.","বিস্তৃত এলাকাজুড়ে জরিপ প্রয়োজন।":"വിശാലമായ പ്രദേശത്തുടനീളം ഒരു സർവേ ആവശ്യമാണ്.","খাবারটি যে খেতে পারি না তা নয়, তবে একটু ঝাল।":"ഭക്ഷണം കഴിക്കാൻ കഴിയില്ലെന്നല്ല, പക്ഷേ അല്പം എരിവുണ്ട്.","গত বছরের তুলনায় ব্যবহারকারী বেড়েছে।":"കഴിഞ്ഞ വർഷത്തെ അപേക്ഷിച്ച് ഉപയോക്താക്കൾ വർദ്ധിച്ചു.","বসন্ত হলেও সকালে এখনো ঠান্ডা।":"വസന്തമാണെങ്കിലും രാവിലെ ഇപ്പോഴും തണുപ്പാണ്.","যান বা না যান, জানাবেন।":"നിങ്ങൾ പോയാലും ഇല്ലെങ്കിലും, ദയവായി ഞങ്ങളെ അറിയിക്കുക.","এভাবে চললে দুর্ঘটনার আশঙ্কা আছে।":"ഇങ്ങനെ തുടർന്നാൽ ഒരു അപകടത്തിന് സാധ്യതയുണ്ട്.","বাইরে বের হওয়া মাত্রই বৃষ্টি শুরু হলো।":"ഞാൻ പുറത്തിറങ്ങിയ ഉടൻ മഴ പെയ്യാൻ തുടങ്ങി.","বন্ধুর সঙ্গে দেখা হওয়ার সূত্রে আমার চিন্তা বদলেছে।":"എന്റെ സുഹൃത്തിനെ കണ്ടുമുട്ടിയ അവസരത്തിൽ എന്റെ ചിന്തകൾ മാറി.","না করলেও ভদ্রভাবে জানানো ভালো।":"നിങ്ങൾ അത് ചെയ്തില്ലെങ്കിലും, അവരെ അറിയിക്കുന്നത് മാന്യമാണ്.","টোকিওর তুলনায় এই শহরে ভাড়া কম।":"ടോക്കിയോയെ അപേക്ഷിച്ച് ഈ നഗരത്തിൽ വാടക കുറവാണ്.","এইমাত্র বেরিয়েছে, তাই ইতিমধ্যে পৌঁছে যাওয়ার কথা নয়।":"അദ്ദേഹം ഇപ്പോൾ പുറപ്പെട്ടതേയുള്ളൂ, അതിനാൽ അദ്ദേഹം ഇതിനകം എത്തിയിരിക്കാൻ സാധ്യതയില്ല.","বিষয়বস্তু যাচাই করার পরে স্বাক্ষর করুন।":"ഉള്ളടക്കം പരിശോധിച്ച ശേഷം ദയവായി ഒപ്പിടുക.","জাপানিতে অভ্যস্ত হওয়ার সঙ্গে কথা বলা আনন্দদায়ক হয়েছে।":"ജാപ്പനീസുമായി പരിചയപ്പെട്ടതിനനുസരിച്ച് അത് സംസാരിക്കുന്നത് ആസ്വാദ്യകരമായി.","কথা দিয়েছি বলে এখন আর না করা চলে না।":"ഞാൻ ഒരു വാഗ്ദാനം ചെയ്തതിനാൽ, ഇപ്പോൾ എനിക്ക് പിന്മാറാൻ കഴിയില്ല.","এই প্রস্তাব সম্পর্কে আমার প্রশ্ন আছে।":"ഈ നിർദ്ദേശത്തെക്കുറിച്ച് എനിക്ക് ഒരു ചോദ്യമുണ്ട്.","মতবিনিময় অনুষ্ঠানকে উপলক্ষ করে স্থানীয় কাজে যুক্ত হয়েছি।":"അഭിപ്രായ വിനിമയ യോഗത്തെ ഒരു അവസരമാക്കി, ഞാൻ പ്രാദേശിക ജോലികളിൽ ഇടപെട്ടു.","ট্রেন বন্ধ হওয়ায় ট্যাক্সি নেওয়া ছাড়া উপায় ছিল না।":"ട്രെയിനുകൾ നിർത്തിവച്ചതിനാൽ, ടാക്സി എടുക്കുകയല്ലാതെ എനിക്ക് മറ്റൊരു വഴിയുമില്ലായിരുന്നു.","তিনি হাল না ছেড়ে অনুশীলন চালিয়েছেন।":"അദ്ദേഹം ഉപേക്ഷിക്കാതെ പരിശീലനം തുടർന്നു.","মনে হচ্ছিল যেন স্বপ্ন দেখছি।":"ഞാൻ സ്വപ്നം കാണുകയാണെന്ന് തോന്നി.","অতিথির চাহিদা অনুযায়ী কক্ষের ব্যবস্থা করব।":"അതിഥിയുടെ അഭ്യർത്ഥനകൾക്കനുസരിച്ച് ഞങ്ങൾ മുറി ഒരുക്കും.","প্রিয় বন্ধু বলেই সৎভাবে জানাতে চাই।":"നിങ്ങൾ പ്രിയപ്പെട്ട സുഹൃത്തായതുകൊണ്ട് തന്നെ, സത്യസന്ധമായി പറയാൻ ഞാൻ ആഗ്രഹിക്കുന്നു.","প্রতিদিন অনুশীলন করছে, নিশ্চয়ই দক্ষ হবে বলে মনে করি।":"അവർ എല്ലാ ദിവസവും പരിശീലിക്കുന്നുണ്ട്, അതിനാൽ അവർ തീർച്ചയായും വൈദഗ്ധ്യം നേടുമെന്ന് ഞാൻ കരുതുന്നു.","ব্যাখ্যা পড়েছি ঠিকই, কিন্তু ব্যবহারের পদ্ধতি এখনো বুঝিনি।":"ഞാൻ വിശദീകരണം വായിച്ചു, പക്ഷേ അത് എങ്ങനെ ഉപയോഗിക്കണമെന്ന് എനിക്ക് ഇപ്പോഴും മനസ്സിലായിട്ടില്ല.","দোকানটি সারা বছর খোলা থাকে।":"കട വർഷം മുഴുവൻ തുറന്നിരിക്കും.","এত সহজ উপায়ে সব মনে রাখা যাবে, এমন নয় মোটেও।":"ഇത്ര എളുപ്പത്തിൽ എല്ലാം ഓർമ്മിക്കാൻ കഴിയുമെന്ന് ഒരിക്കലും പറയാനാവില്ല.","শুধু বিদেশি শিক্ষার্থী নয়, এলাকার মানুষও অংশ নিতে পারেন।":"വിദേശ വിദ്യാർത്ഥികൾക്ക് മാത്രമല്ല, നാട്ടുകാർക്കും പങ്കെടുക്കാം.","আমার জানা মতে দোকানটি রবিবারও খোলা থাকে।":"എന്റെ അറിവിൽ, കട ഞായറാഴ്ചകളിലും തുറന്നിരിക്കും.","ব্যবস্থার পরিবর্তনের সঙ্গে প্রক্রিয়াও বদলেছে।":"സംവിധാനത്തിലെ മാറ്റത്തോടെ, പ്രക്രിയയും മാറി.","টাইফুনের কারণে ট্রেন বন্ধ হওয়ার আশঙ্কা আছে।":"ചുഴലിക്കാറ്റ് കാരണം ട്രെയിനുകൾ നിർത്തിവയ്ക്കാൻ സാധ്യതയുണ്ട്.","তিনি পথঘাট ভালো জানেন, নিশ্চয়ই স্থানীয় বলে মনে হয়।":"അദ്ദേഹത്തിന് റോഡുകൾ നന്നായി അറിയാം, അതിനാൽ അദ്ദേഹം തീർച്ചയായും ഒരു നാട്ടുകാരനാണെന്ന് തോന്നുന്നു.","জ্বর আছে বলে বিশ্রাম না নিয়ে থাকা চলে না।":"പനി ഉള്ളതിനാൽ, വിശ്രമിക്കാതിരിക്കാൻ എനിക്ക് കഴിയില്ല.","মতবিনিময় অনুষ্ঠানের মাধ্যমে নতুন বন্ধু হয়েছে।":"വിനിമയ പരിപാടിയിലൂടെ ഞാൻ പുതിയ സുഹൃത്തുക്കളെ ഉണ്ടാക്കി.","সুস্থ থাকা পর্যন্ত কাজ চালিয়ে যেতে চাই।":"ഞാൻ ആരോഗ്യവാനായിരിക്കുന്നിടത്തോളം ജോലി തുടരാൻ ഞാൻ ആഗ്രഹിക്കുന്നു.","সফল হব কি না তা প্রস্তুতির ওপর নির্ভর করে।":"ഞാൻ വിജയിക്കുമോ ഇല്ലയോ എന്നത് എന്റെ തയ്യാറെടുപ്പിനെ ആശ്രയിച്ചിരിക്കുന്നു.","আকাশ অন্ধকার হলো মনে হতেই প্রবল বৃষ্টি নামল।":"ആകാശം ഇരുണ്ടതായി തോന്നിയ നിമിഷം, കനത്ത മഴ പെയ്യാൻ തുടങ്ങി.","বড় ভাই সকালে স্বচ্ছন্দ, এর বিপরীতে ছোট ভাই রাতে স্বচ্ছন্দ।":"മൂത്ത സഹോദരന് രാവിലെ സുഖമാണ്, എന്നാൽ ഇളയ സഹോദരന് രാത്രിയാണ് സുഖം.","ছোটবেলায় নদীতে প্রায়ই খেলতাম।":"ഞാൻ ചെറുപ്പമായിരുന്നപ്പോൾ, ഞാൻ പലപ്പോഴും നദിയിൽ കളിക്കാറുണ്ടായിരുന്നു.","এটি বাস্তব অভিজ্ঞতার ভিত্তিতে লেখা প্রতিবেদন।":"യഥാർത്ഥ അനുഭവത്തെ അടിസ്ഥാനമാക്കി എഴുതിയ ഒരു റിപ്പോർട്ടാണിത്.","বিদেশের জীবন আনন্দের, আবার পরিবারের জন্য মনও খারাপ হয়।":"വിദേശത്തെ ജീവിതം രസകരമാണ്, പക്ഷേ എനിക്ക് എന്റെ കുടുംബത്തെയും മിസ് ചെയ്യുന്നു.","অংশ নিন বা না নিন, উত্তর দিন।":"നിങ്ങൾ പങ്കെടുത്താലും ഇല്ലെങ്കിലും, ദയവായി ഉത്തരം നൽകുക.","এই সমস্যা শুধু জাপানে নয়, অন্য দেশেও আছে।":"ഈ പ്രശ്നം ജപ്പാനിൽ മാത്രമല്ല, മറ്റ് രാജ്യങ്ങളിലും ഉണ്ട്.","কক্ষটি শান্ত বলার চেয়ে বরং নির্জন লাগে।":"മുറി ശാന്തമാണെന്ന് പറയുന്നതിനേക്കാൾ, അത് വിജനമാണെന്ന് തോന്നുന്നു.","তিন দিনজুড়ে প্রশিক্ষণ অনুষ্ঠিত হয়েছে।":"മൂന്ന് ദിവസങ്ങളിലായി പരിശീലനം നടന്നു.","শহর একদিকে সুবিধাজনক, অন্যদিকে জীবনযাত্রার খরচ বেশি।":"നഗരം ഒരു വശത്ത് സൗകര്യപ്രദമാണ്, മറുവശത്ത് ജീവിതച്ചെലവ് കൂടുതലാണ്.","কারণ না জেনে বিচার করা উচিত নয়।":"കാരണം അറിയാതെ നിങ്ങൾ വിധി പറയരുത്.","জাপানি হলেও সবাই যে কানজিতে দক্ষ তা নয়।":"ഒരാൾ ജാപ്പനീസ് ആണെന്നതുകൊണ്ട് അവർ കാൻജിയിൽ മിടുക്കരാണെന്ന് അർത്ഥമില്ല.","গ্রাহকসেবার ক্ষেত্রে অন্যের কথা শোনা জরুরি।":"ഉപഭോക്തൃ സേവനത്തിൽ, മറ്റുള്ളവരെ ശ്രദ്ധിക്കുന്നത് അത്യാവശ്യമാണ്.","জাপানি বলতে পারলেও সম্মানসূচক ভাষায় আত্মবিশ্বাস নেই।":"എനിക്ക് ജാപ്പനീസ് സംസാരിക്കാൻ കഴിയുമെങ്കിലും, ബഹുമാന ഭാഷയിൽ എനിക്ക് ആത്മവിശ്വാസമില്ല.","কণ্ঠস্বর শোনা মাত্রই স্বস্তি পেলাম।":"ആ ശബ്ദം കേട്ട നിമിഷം, എനിക്ക് ആശ്വാസം തോന്നി.","অভিজ্ঞতার সঙ্গে মানানসই কাজের দায়িত্ব দেব।":"അവരുടെ അനുഭവത്തിന് അനുയോജ്യമായ ജോലി ഉത്തരവാദിത്തങ്ങൾ ഞാൻ നൽകും.","আগে বন্ধুদের সঙ্গে প্রায়ই দীর্ঘ চিঠি লিখতাম।":"മുൻകാലങ്ങളിൽ, ഞാൻ പലപ്പോഴും എന്റെ സുഹൃത്തുക്കൾക്ക് നീണ്ട കത്തുകൾ എഴുതാറുണ്ടായിരുന്നു.","সুবিধা বেড়েছে ঠিকই, তবু সমস্যা রয়ে গেছে।":"സൗകര്യം വർദ്ധിച്ചു, ശരിയാണ്, പക്ഷേ പ്രശ്നങ്ങൾ അവശേഷിക്കുന്നു.","জরিপের ফলকে ভিত্তি করে পরিকল্পনা করেছি।":"സർവേ ഫലങ്ങളെ അടിസ്ഥാനമാക്കിയാണ് ഞങ്ങൾ പദ്ധതി തയ്യാറാക്കിയത്.","চালিয়ে যেতে পেরেছি ঠিক সহকর্মীরা পাশে ছিলেন বলেই।":"എന്റെ സഹപ്രവർത്തകർ എന്റെ കൂടെ നിന്നതുകൊണ്ട് തന്നെ എനിക്ക് തുടരാൻ കഴിഞ്ഞു.","তিনি এমনভাবে কথা বললেন যেন কিছুই জানেন না।":"അദ്ദേഹം അതിനെക്കുറിച്ച് ഒന്നും അറിയാത്തതുപോലെ സംസാരിച്ചു.","বন্ধুর জন্য চিন্তায় যোগাযোগ না করে থাকতে পারিনি।":"എന്റെ സുഹൃത്തിനെക്കുറിച്ച് ആശങ്കയുള്ളതിനാൽ, അവരെ ബന്ധപ്പെടാതിരിക്കാൻ എനിക്ക് കഴിഞ്ഞില്ല.","দামি জিনিস সবসময় ভালো হবে এমন নয়।":"വിലയേറിയ വസ്തുക്കൾ എല്ലായ്പ്പോഴും നല്ലതല്ല.","সহযোগিতা হলো একই লক্ষ্যে একসঙ্গে কাজ করা।":"സഹകരണം എന്നാൽ ഒരേ ലക്ഷ്യത്തിനായി ഒരുമിച്ച് പ്രവർത്തിക്കുക എന്നാണ്.","প্রবল বৃষ্টিতে পরিকল্পনা বদলানো ছাড়া উপায় নেই।":"കനത്ത മഴയുള്ളതിനാൽ, ഞങ്ങളുടെ പദ്ധതികൾ മാറ്റുകയല്ലാതെ മറ്റൊരു വഴിയുമില്ല.","সূচি ঠিক হওয়া মাত্র জানাব।":"ഷെഡ്യൂൾ അന്തിമമായ ഉടൻ ഞാൻ നിങ്ങളെ അറിയിക്കും.","বয়স নির্বিশেষে যে কেউ অংশ নিতে পারেন।":"പ്രായഭേദമന്യേ ആർക്കും പങ്കെടുക്കാം.","কেইগো বলতে অন্যের প্রতি সম্মান প্রকাশের ভাষা বোঝায়।":"മറ്റുള്ളവരോട് ബഹുമാനം പ്രകടിപ്പിക്കാൻ ഉപയോഗിക്കുന്ന ഭാഷയെയാണ് കെയ്ഗോ എന്ന് പറയുന്നത്.","জনসংখ্যা বৃদ্ধির সঙ্গে আবাসনের প্রয়োজন বেড়েছে।":"ജനസംഖ്യ വർദ്ധിച്ചതോടെ, ഭവനങ്ങളുടെ ആവശ്യവും വർദ്ധിച്ചു.","আমি শুধু মতামত জানিয়েছি।":"ഞാൻ എന്റെ അഭിപ്രായം മാത്രമാണ് പറഞ്ഞത്.","এবারের সাফল্য আপনাদের পরিশ্রমের ফলই।":"ഈ വിജയം നിങ്ങളുടെ കഠിനാധ്വാനത്തിന്റെ ഫലമല്ലാതെ മറ്റൊന്നുമല്ല.","ঘটনাটি শুনলে না হেসে থাকতে পারি না।":"കഥ കേട്ടപ്പോൾ, ചിരിക്കാതിരിക്കാൻ എനിക്ക് കഴിഞ്ഞില്ല.","এটি কেবল একটি উদাহরণ।":"ഇത് വെറുമൊരു ഉദാഹരണം മാത്രമാണ്."},"lessons.explanation_bn":{"বক্তার দেখা দুটি ঘটনা খুব দ্রুত বদলে যায়। প্রথম অবস্থা বুঝে ওঠার আগেই পরের অবস্থা আসে—এই পরিবর্তনকে তুলে ধরে।":"സ്പീക്കർ നിരീക്ഷിക്കുന്ന രണ്ട് സംഭവങ്ങൾ വളരെ വേഗത്തിൽ മാറുന്നു. ആദ്യ അവസ്ഥ പൂർണ്ണമായി മനസ്സിലാക്കുന്നതിന് മുമ്പ് അടുത്ത അവസ്ഥ എത്തുന്നു എന്ന ദ്രുത മാറ്റത്തെ ഇത് എടുത്തുകാണിക്കുന്നു.","একটি ঘটনা বড় পরিবর্তন, নতুন অভ্যাস বা সম্পর্কের সূচনা করে। শুধু যেকোনো কারণ নয়, শুরু হওয়ার উপলক্ষকে জোর দেয়।":"ഒരു സംഭവം ഒരു വലിയ മാറ്റത്തിനോ പുതിയ ശീലത്തിനോ ബന്ധത്തിനോ തുടക്കമിടുന്നു. വെറുമൊരു കാരണമല്ല, തുടങ്ങുന്ന അവസരത്തെയാണ് ഇത് ഊന്നിപ്പറയുന്നത്.","কাজটি করতে সক্ষম হলেও দায়িত্ব, প্রতিশ্রুতি বা সামাজিক কারণে তা করা গ্রহণযোগ্য নয়। নেতিবাচক ক্রিয়ার সঙ্গে “না করে থাকা চলে না”, অর্থাৎ করতেই হবে।":"ഒരാൾക്ക് ആ പ്രവൃത്തി ചെയ്യാൻ കഴിവുണ്ടെങ്കിലും, ഉത്തരവാദിത്തം, വാഗ്ദാനം അല്ലെങ്കിൽ സാമൂഹിക കാരണങ്ങളാൽ അത് ചെയ്യുന്നത് സ്വീകാര്യമല്ല. നിഷേധ ക്രിയകളോടൊപ്പം, ഇതിനർത്ഥം \"ചെയ്യാതിരിക്കാൻ കഴിയില്ല\" എന്നാണ്, അതായത് അത് ചെയ്യേണ്ടതാണ്.","কোনো শব্দ বা ধারণাকে সামনে এনে তার অর্থ, সংজ্ঞা বা মূল বৈশিষ্ট্য ব্যাখ্যা করুন। প্রবন্ধ ও ব্যাখ্যামূলক লেখায় মানায়।":"ഒരു വാക്കോ ആശയമോ മുന്നോട്ട് കൊണ്ടുവന്ന് അതിന്റെ അർത്ഥം, നിർവചനം അല്ലെങ്കിൽ പ്രധാന സവിശേഷതകൾ വിശദീകരിക്കുക. ഉപന്യാസങ്ങൾക്കും വിശദീകരണ രചനകൾക്കും അനുയോജ്യം.","পরিমাণ, ভূমিকা বা গুরুত্বকে সীমিত করে বোঝায়। বক্তা মনে করেন বিষয়টিকে তার চেয়ে বড় করে দেখা ঠিক নয়।":"അളവ്, പങ്ക് അല്ലെങ്കിൽ പ്രാധാന്യം പരിമിതപ്പെടുത്തുന്നു. വിഷയത്തെ അതിനേക്കാൾ വലുതായി കാണുന്നത് ശരിയല്ലെന്ന് സ്പീക്കർക്ക് തോന്നുന്നു.","Vた-এর সঙ্গে প্রথম কাজ ভালোভাবে করে তারপর সিদ্ধান্ত বা কাজ করুন। Vる-এর সঙ্গে কোনো কাজের ক্ষেত্রে কী গুরুত্বপূর্ণ তা ব্যাখ্যা করুন।":"Vた ഉപയോഗിക്കുമ്പോൾ, തീരുമാനിക്കുന്നതിനോ പ്രവർത്തിക്കുന്നതിനോ മുമ്പ് ആദ്യ പ്രവൃത്തി ശരിയായി പൂർത്തിയാക്കുക. Vる ഉപയോഗിക്കുമ്പോൾ, ഒരു പ്രത്യേക പ്രവൃത്തി ചെയ്യുമ്പോൾ എന്താണ് പ്രധാനമെന്ന് വിശദീകരിക്കുക.","বাস্তবে ঠিক সেই অবস্থা না হলেও তেমন দেখায় বা অনুভূত হয়। কল্পনা ও উপমা তৈরি করতে ব্যবহার করুন।":"യാഥാർത്ഥ്യത്തിൽ അങ്ങനെയല്ലെങ്കിലും, അങ്ങനെ തോന്നുകയോ കാണപ്പെടുകയോ ചെയ്യുന്നു. ഭാവനയും ഉപമകളും സൃഷ്ടിക്കാൻ ഇത് ഉപയോഗിക്കുക.","পরিচয় বা আসল কারণকে জোর দিয়ে নির্দিষ্ট করে। বক্তা দৃঢ়ভাবে বলেন, এটিই আসল ব্যাখ্যা। আনুষ্ঠানিক যুক্তি বা মূল্যায়নে উপযোগী।":"ഒരു ഐഡന്റിറ്റിയെയോ യഥാർത്ഥ കാരണത്തെയോ ഊന്നിപ്പറഞ്ഞ് വ്യക്തമാക്കുന്നു. ഇതാണ് യഥാർത്ഥ വിശദീകരണമെന്ന് സ്പീക്കർ ഉറച്ച് ഉറപ്പിക്കുന്നു. ഔപചാരിക യുക്തിയിലോ മൂല്യനിർണ്ണയത്തിലോ ഉപയോഗപ്രദം.","চাহিদা, ক্ষমতা, পরিস্থিতি বা পরিবর্তনের সঙ্গে সামঞ্জস্য রেখে কাজ বা ব্যবস্থা বদলায়। সবার জন্য একই ব্যবস্থা বোঝায় না।":"ആവശ്യങ്ങൾ, കഴിവുകൾ, സാഹചര്യങ്ങൾ അല്ലെങ്കിൽ മാറ്റങ്ങൾ എന്നിവയുമായി പൊരുത്തപ്പെടാൻ പ്രവൃത്തികളോ ക്രമീകരണങ്ങളോ മാറുന്നു. എല്ലാവർക്കും ഒരേ ക്രമീകരണം എന്നല്ല ഇതിനർത്ഥം.","একই বিষয় বা পরিস্থিতির দুটি ভিন্ন দিক পাশাপাশি তুলে ধরে। ভালো-মন্দ, সুবিধা-অসুবিধা বা পরস্পর ভিন্ন প্রবণতা তুলনা করা যায়।":"ഒരേ വിഷയത്തിന്റെയോ സാഹചര്യത്തിന്റെയോ രണ്ട് വ്യത്യസ്ത വശങ്ങൾ വശങ്ങളിലായി അവതരിപ്പിക്കുന്നു. നല്ലതും ചീത്തയും, ഗുണങ്ങളും ദോഷങ്ങളും, അല്ലെങ്കിൽ പരസ്പര വ്യത്യസ്ത പ്രവണതകളും താരതമ്യം ചെയ്യാം.","একটি বড় পরিবর্তন বা ঘটনার সঙ্গে সম্পর্কিত আরেকটি পরিবর্তন ঘটে। সামাজিক প্রবণতা, নীতি ও সংখ্যা ব্যাখ্যায় উপযোগী।":"ഒരു വലിയ മാറ്റവുമായോ സംഭവവുമായോ ബന്ധപ്പെട്ട് മറ്റൊരു മാറ്റം സംഭവിക്കുന്നു. സാമൂഹിക പ്രവണതകൾ, നയങ്ങൾ, സംഖ്യകൾ എന്നിവ വിശദീകരിക്കാൻ ഉപയോഗപ്രദം.","আগের অবস্থা বা শর্ত বজায় থাকা পর্যন্ত পরের কথা সত্য। 知[し]っている限[かぎ]り বলতে নিজের জানার সীমার মধ্যেও বোঝায়।":"മുൻ അവസ്ഥയോ ഷർത്തോ തുടരുന്നിടത്തോളം, തുടർന്നുള്ളത് സത്യമാണ്. 知[し]っている限[かぎ]り എന്നാൽ ഒരാൾക്ക് അറിയാവുന്നതിന്റെ പരിധിക്കുള്ളിൽ എന്നും അർത്ഥമുണ്ട്.","কারণ বা পরিস্থিতি বিবেচনা করে বক্তা প্রবলভাবে সম্ভাবনা অস্বীকার করেন। এটি বক্তার দৃঢ় বিচার; বৈজ্ঞানিক নিশ্চয়তা দাবি নয়।":"കാരണമോ സാഹചര്യമോ കണക്കിലെടുത്ത്, സ്പീക്കർ സാധ്യതയെ ശക്തമായി നിഷേധിക്കുന്നു. ഇത് സ്പീക്കറുടെ ഉറച്ച വിധിയാണ്; ഇത് ശാസ്ത്രീയ ഉറപ്പ് അവകാശപ്പെടുന്നില്ല.","নিয়ম, তথ্য, গবেষণা বা অভিজ্ঞতাকে সিদ্ধান্তের ভিত্তি হিসেবে ব্যবহার করা হয়। অনুমানের বদলে কী ভিত্তির ওপর কাজ হয়েছে তা বলুন।":"നിയമങ്ങൾ, വിവരങ്ങൾ, ഗവേഷണം അല്ലെങ്കിൽ അനുഭവം എന്നിവ ഒരു തീരുമാനത്തിന് അടിസ്ഥാനമായി ഉപയോഗിക്കുന്നു. ഊഹത്തിന് പകരം, ജോലി എന്തിനെ അടിസ്ഥാനമാക്കിയുള്ളതാണെന്ന് പറയുക.","কাজ বা অবস্থা দীর্ঘ সময়, বিস্তৃত এলাকা বা বহু বিষয়ের পরিসরজুড়ে চলেছে বোঝায়। পরিসরের বিস্তারকে গুরুত্ব দেয়।":"ഒരു പ്രവൃത്തിയോ അവസ്ഥയോ ദീർഘകാലം, വിശാലമായ പ്രദേശം അല്ലെങ്കിൽ വിശാലമായ വിഷയങ്ങളിൽ തുടരുന്നുവെന്ന് സൂചിപ്പിക്കുന്നു. വ്യാപ്തിയുടെ വിസ്തൃതിയെ ഊന്നിപ്പറയുന്നു.","অন্য বিকল্প না থাকায় অনিচ্ছা সত্ত্বেও কাজটি করতে হয়। বাইরের পরিস্থিতি বা বাস্তব সীমাবদ্ধতা বক্তাকে বাধ্য করে।":"മറ്റ് ബദലുകൾ ഇല്ലാത്തതിനാൽ, മനസ്സില്ലാമനസ്സോടെയാണെങ്കിലും ഒരാൾക്ക് ആ ജോലി ചെയ്യേണ്ടി വരുന്നു. ബാഹ്യ സാഹചര്യങ്ങളോ പ്രായോഗിക പരിമിതികളോ സ്പീക്കറെ നിർബന്ധിക്കുന്നു.","আবেগ বা প্রবল স্বাভাবিক তাড়নায় কাজটি না করে থাকা যায় না। নিজের অনুভূতি বা সহজে বোঝা প্রতিক্রিয়া প্রকাশে মানায়।":"ശക്തമായ സ്വാഭാവിക വികാരങ്ങളാലോ പ്രേരണകളാലോ നയിക്കപ്പെട്ട്, എന്തെങ്കിലും ചെയ്യാതിരിക്കാൻ നിങ്ങൾക്ക് കഴിയില്ല. ഒരാളുടെ വികാരങ്ങളോ എളുപ്പത്തിൽ മനസ്സിലാക്കാവുന്ന പ്രതികരണങ്ങളോ പ്രകടിപ്പിക്കാൻ അനുയോജ്യം.","একটি শ্রেণির বাইরে একই কথা আরও বিস্তৃত শ্রেণিতেও প্রযোজ্য হলে ব্যবহার করুন। পরে も বা 広[ひろ]く-এর মতো বিস্তারের ইঙ্গিত থাকতে পারে।":"ഒരേ കാര്യം ഒരു വിഭാഗത്തിന് മാത്രമല്ല, അതിനപ്പുറമുള്ള വിശാലമായ വിഭാഗത്തിനും ബാധകമാകുമ്പോൾ ഇത് ഉപയോഗിക്കുക. പിന്നീട് വാക്യത്തിൽ も അല്ലെങ്കിൽ 広[ひろ]く പോലുള്ള വ്യാപനത്തിന്റെ സൂചന ഉണ്ടായിരിക്കാം.","আগের তথ্য স্বীকার করেও সীমাবদ্ধতা, ব্যতিক্রম বা সতর্কতা জানান। প্রথম কথাটি মিথ্যা না বলে তাকে শর্তসাপেক্ষ করেন।":"മുൻ വിവരങ്ങൾ അംഗീകരിച്ചുകൊണ്ട് ഒരു പരിമിതി, ഒഴിവാക്കൽ അല്ലെങ്കിൽ മുന്നറിയിപ്പ് പറയുന്നു. ആദ്യ പ്രസ്താവനയെ തെറ്റാണെന്ന് പറയാതെ അതിനെ ഷർത്തുള്ളതാക്കുന്നു.","আগের কাজ ঘটার সঙ্গে সঙ্গেই অপ্রত্যাশিত পরিবর্তন বা ঘটনা ঘটে। পরের অংশে সাধারণত পরিকল্পিত নির্দেশ বা ইচ্ছা থাকে না।":"മുൻ പ്രവൃത്തിക്ക് തൊട്ടുപിന്നാലെ അപ്രതീക്ഷിതമായ ഒരു മാറ്റമോ സംഭവമോ സംഭവിക്കുന്നു. രണ്ടാം പകുതിയിൽ സാധാരണയായി മനഃപൂർവ്വമായ കല്പനകളോ ആഗ്രഹങ്ങളോ ഉണ്ടാകില്ല.","লক্ষণ, পরিস্থিতি বা জানা তথ্য থেকে বক্তা শক্ত অনুমান করেন। সরাসরি দেখা প্রমাণিত ঘটনা বলার বদলে নিজের বিচার প্রকাশ পায়।":"അടയാളങ്ങൾ, സാഹചര്യങ്ങൾ അല്ലെങ്കിൽ അറിയാവുന്ന വിവരങ്ങൾ എന്നിവയെ അടിസ്ഥാനമാക്കി സ്പീക്കർ ശക്തമായ ഒരു ഊഹം നടത്തുന്നു. നേരിട്ട് നിരീക്ഷിച്ച തെളിയിക്കപ്പെട്ട വസ്തുതകൾ പറയുന്നതിന് പകരം, അത് ഒരാളുടെ സ്വന്തം വിധിയെ പ്രകടിപ്പിക്കുന്നു.","ক্রিয়ার ます বাদ দেওয়া রূপে কোনো কাজ শেষ হলে দ্রুত পরের কাজ করার পরিকল্পনা জানায়। বিশেষ্যের সঙ্গে ফল নির্ভর করার অর্থ হয়।":"ക്രിയയിൽ നിന്ന് ます ഒഴിവാക്കി ഒരു പ്രവൃത്തി പൂർത്തിയാക്കിയ ശേഷം അടുത്ത പ്രവൃത്തി വേഗത്തിൽ ചെയ്യാനുള്ള പദ്ധതിയെ ഇത് സൂചിപ്പിക്കുന്നു. ഒരു നാമത്തോടൊപ്പം ഉപയോഗിക്കുമ്പോൾ, ഫലത്തെ ആശ്രയിച്ചിരിക്കുന്നു എന്നാണ് അർത്ഥം.","একটি পরিস্থিতি সত্য ধরে নিয়েও পরের মতামত বা সীমা বলুন। জোড়ায় AにしてもBにしても হলে উভয় ক্ষেত্রেই একই কথা প্রযোজ্য।":"ഒരു സാഹചര്യം സത്യമാണെന്ന് കരുതിയാലും തുടർന്നുള്ള അഭിപ്രായമോ പരിമിതിയോ പറയുക. AにしてもBにしても എന്ന് ജോടിയാക്കുമ്പോൾ, രണ്ട് സന്ദർഭങ്ങൾക്കും ഒരേ കാര്യം ബാധകമാണ്.","প্রথম বর্ণনাটি পুরো ঠিক নয় মনে করে তার চেয়ে মানানসই দ্বিতীয় বর্ণনা দিন। বিরোধিতা নয়, আরও যথাযথ ভাষায় সংশোধন।":"ആദ്യ വിവരണം പൂർണ്ണമായും ശരിയല്ലെന്ന് കരുതി, കൂടുതൽ അനുയോജ്യമായ രണ്ടാമത്തെ വിവരണം നൽകുക. എതിർപ്പല്ല, കൂടുതൽ ഉചിതമായ ഭാഷയിലുള്ള തിരുത്തലാണ്.","একটি কারণকে বিশেষ গুরুত্ব দিয়ে ফলের সঙ্গে জুড়ে দেয়। কারণটি দুর্বল নয়; বক্তা সেটিকেই মূল প্রেরণা হিসেবে সামনে আনছেন।":"ഒരു കാരണത്തിന് പ്രത്യേക ഊന്നൽ നൽകി അതിനെ ഫലവുമായി ബന്ധിപ്പിക്കുന്നു. കാരണം ദുർബലമല്ല; സ്പീക്കർ അതിനെ പ്രധാന പ്രചോദനമായി മുന്നോട്ട് കൊണ്ടുവരുന്നു.","একটি কাজ বা অবস্থা ঘটানো ছাড়া পরের কাজ ঘটে। লিখিত বা আনুষ্ঠানিক ভাষায় Vないで-এর কাছাকাছি অর্থ।":"ഒരു പ്രത്യേക പ്രവൃത്തിയോ അവസ്ഥയോ സംഭവിക്കാതെ അടുത്ത പ്രവൃത്തി സംഭവിക്കുന്നു. രേഖാമൂലമുള്ള അല്ലെങ്കിൽ ഔപചാരിക ഭാഷയിൽ Vないで-ന് അടുത്ത അർത്ഥം.","আগের তথ্য সত্য মেনে নিয়ে পরের অংশে তার প্রত্যাশিত ফল না হওয়ার কথা বলুন। লিখিত বা কিছুটা আনুষ্ঠানিক ব্যাখ্যায় বেশি মানায়।":"മുൻ വിവരങ്ങൾ സത്യമായി അംഗീകരിച്ച്, പ്രതീക്ഷിച്ച ഫലം തുടർന്നുള്ള ഭാഗത്ത് ഉണ്ടാകുന്നില്ലെന്ന് പറയുക. രേഖാമൂലമുള്ള അല്ലെങ്കിൽ അല്പം ഔപചാരിക വിശദീകരണങ്ങൾക്ക് ഇത് കൂടുതൽ അനുയോജ്യമാണ്.","নেতিবাচক কথাটিকে পুরোপুরি মানতে চান না। সীমিত সক্ষমতা, আংশিক সত্য বা শর্তসাপেক্ষ সম্মতি প্রকাশ করেন।":"നിഷേധ പ്രസ്താവന പൂർണ്ണമായും അംഗീകരിക്കാൻ നിങ്ങൾ ആഗ്രഹിക്കുന്നില്ല. ഇത് പരിമിതമായ കഴിവ്, ഭാഗിക സത്യം അല്ലെങ്കിൽ ഷർത്തുള്ള സമ്മതം എന്നിവ പ്രകടിപ്പിക്കുന്നു.","একটি তুলনার মানদণ্ড নির্দিষ্ট করে পরের তথ্যের পার্থক্য দেখায়। হার, দাম, অতীত ও বর্তমান তুলনায় কাজে আসে।":"താരതമ്യത്തിനുള്ള ഒരു മാനദണ്ഡം വ്യക്തമാക്കുകയും തുടർന്നുള്ള വിവരങ്ങളിലെ വ്യത്യാസം കാണിക്കുകയും ചെയ്യുന്നു. നിരക്കുകൾ, വിലകൾ, ഭൂതവും വർത്തമാനവും താരതമ്യം ചെയ്യാൻ ഉപയോഗപ്രദം.","একটি পরিবর্তন অগ্রসর হওয়ার সঙ্গে অন্য একটি অবস্থাও ধীরে বদলায়। বয়স, সময় বা অভিজ্ঞতার বৃদ্ধি বোঝাতে সুবিধাজনক।":"ഒരു മാറ്റം പുരോഗമിക്കുന്നതിനനുസരിച്ച്, മറ്റൊരു അവസ്ഥയും ക്രമേണ മാറുന്നു. പ്രായം, സമയം അല്ലെങ്കിൽ അനുഭവം എന്നിവയിലെ വർദ്ധനവ് പ്രകടിപ്പിക്കാൻ ഉപയോഗപ്രദം.","কাজ বা অনুভূতির লক্ষ্য বোঝায়। দুটি পক্ষের বিপরীত বৈশিষ্ট্য তুলনা করতেও ব্যবহার হয়; কোন ব্যবহার তা প্রসঙ্গ দেখে ধরুন।":"ഒരു പ്രവൃത്തിയുടെയോ വികാരത്തിന്റെയോ ലക്ഷ്യത്തെ സൂചിപ്പിക്കുന്നു. രണ്ട് കക്ഷികളുടെ വിപരീത സവിശേഷതകൾ താരതമ്യം ചെയ്യാനും ഉപയോഗിക്കുന്നു; ഏത് ഉപയോഗമാണ് ബാധകമെന്ന് സന്ദർഭത്തിൽ നിന്ന് തീരുമാനിക്കുക.","কোনো অভিজ্ঞতা, মাধ্যম বা ব্যক্তির সাহায্যে ফল পাওয়া বোঝায়। সময়ের বিশেষ্যের সঙ্গে পুরো সময়জুড়েও বোঝাতে পারে।":"ഒരു അനുഭവം, മാധ്യമം അല്ലെങ്കിൽ വ്യക്തി എന്നിവയുടെ സഹായത്തോടെ ഒരു ഫലം ലഭിക്കുന്നുവെന്ന് സൂചിപ്പിക്കുന്നു. സമയ നാമങ്ങളോടൊപ്പം, മുഴുവൻ ദൈർഘ്യത്തെയും സൂചിപ്പിക്കാനും കഴിയും.","আগের বিষয়টি যাই হোক, পরের ফল বা নিয়ম বদলায় না। বয়স, অভিজ্ঞতা, আবহাওয়া বা অংশগ্রহণের সিদ্ধান্তে ব্যবহার করা যায়।":"മുൻ വിഷയം എന്തായാലും, തുടർന്നുള്ള ഫലമോ നിയമമോ മാറുന്നില്ല. പ്രായം, അനുഭവം, കാലാവസ്ഥ അല്ലെങ്കിൽ പങ്കെടുക്കാനുള്ള തീരുമാനം എന്നിവയ്ക്ക് ഉപയോഗിക്കാം.","ভবিষ্যতে অনাকাঙ্ক্ষিত ফলের সম্ভাবনা বোঝায়। সংবাদ, সতর্কতা ও আনুষ্ঠানিক ব্যাখ্যায় ব্যবহার হয়।":"ഭാവിയിൽ അഭികാമ്യമല്ലാത്ത ഫലത്തിനുള്ള സാധ്യതയെ സൂചിപ്പിക്കുന്നു. വാർത്തകൾ, മുന്നറിയിപ്പുകൾ, ഔപചാരിക വിശദീകരണങ്ങൾ എന്നിവയിൽ ഉപയോഗിക്കുന്നു.","একটি সাধারণ অনুমান সবার ক্ষেত্রে ঠিক নয়—এই আংশিক নাকচ প্রকাশ করে। কিছু ক্ষেত্রে সত্য হতে পারে, কিন্তু নিশ্চিত নয়।":"ഒരു പൊതുവായ അനുമാനം എല്ലാവർക്കും സത്യമല്ല എന്ന ഭാഗിക നിരാകരണത്തെ ഇത് പ്രകടിപ്പിക്കുന്നു. ചില സന്ദർഭങ്ങളിൽ ഇത് സത്യമായിരിക്കാം, പക്ഷേ അത് ഉറപ്പില്ല.","আগেকার অভ্যাস বা বারবার ঘটত এমন অভিজ্ঞতা স্মরণ করে বলুন। এতে স্মৃতিকাতর ভাব থাকতে পারে।":"മുൻകാലങ്ങളിൽ ആവർത്തിച്ച് സംഭവിച്ചിരുന്ന ശീലങ്ങളോ അനുഭവങ്ങളോ ഓർമ്മിക്കാൻ ഇത് ഉപയോഗിക്കുക. ഇതിൽ ഗൃഹാതുരത്വത്തിന്റെ ഒരു ഭാവം ഉണ്ടായിരിക്കാം."},"lessons.forms":{"必[かなら]ずしも + ইতিবাচক ধারণা + নেতিবাচক predicate":"必[かなら]ずしも + അസ്തിവാചക ആശയം + നിഷേധ predicate","Vない・い-বিশেষণくない + ことはない / N・な-বিশেষণでない + ことはない":"Vない・い-വിശേഷണംくない + ことはない / N・な-വിശേഷണംでない + ことはない","Vない-এর ない বাদ + ずにはいられない（する → せずにはいられない）":"Vない-ൽ നിന്ന് ない നീക്കം ചെയ്യുക + ずにはいられない (する → せずにはいられない)","Plain form + からこそ（N・な-বিশেষণ: だ + からこそ）":"Plain form + からこそ (N・な-വിശേഷണം: だ + からこそ)","V・い-বিশেষণ plain + 一方[いっぽう]で / な-বিশেষণ + な一方[いっぽう]で / N + である一方[いっぽう]で":"V・い-വിശേഷണം plain + 一方[いっぽう]で / な-വിശേഷണം + な一方[いっぽう]で / N + である一方[いっぽう]で","সময়・এলাকা・পরিসর N + にわたって / N + にわたる + N":"സമയം・പ്രദേശം・വ്യാപ്തി N + にわたって / N + にわたる + N","Vる・Vている・Vない + 限[かぎ]り / N・な-বিশেষণである + 限[かぎ]り":"Vる・Vている・Vない + 限[かぎ]り / N・な-വിശേഷണംである + 限[かぎ]り","N + とは + সংজ্ঞা・ব্যাখ্যা":"N + とは + നിർവചനം/വിശദീകരണം","Plain form + とはいえ（N・な-বিশেষণে だ-ও বাদ যায়）":"Plain form + とはいえ (N/な-വിശേഷണങ്ങൾക്ക് だ-യും ഒഴിവാക്കുന്നു)","Vます-stem + 次第[しだい]（সঙ্গে সঙ্গে） / N + 次第[しだい]だ（নির্ভর）":"Vます-stem + 次第[しだい] (ഉടൻ തന്നെ) / N + 次第[しだい]だ (ആശ്രയിച്ചിരിക്കുന്നു)","Vない-এর ない বাদ + ざるを得[え]ない（する → せざるを得[え]ない）":"ない ഇല്ലാതെ Vない + ざるを得[え]ない (する → せざるを得[え]ない)","V・い-বিশেষণ plain + かのようだ / N・な-বিশেষণ + であるかのようだ":"V / い-വിശേഷണം plain + かのようだ / N / な-വിശേഷണം + であるかのようだ","V・い-বিশেষণ plain + に違[ちが]いない / N・な-বিশেষণ + に違[ちが]いない":"V・い-വിശേഷണം plain + に違[ちが]いない / N・な-വിശേഷണം + に違[ちが]いない","V・い-বিশেষণ plain + ものの / な-বিশেষণ + なものの / N + であるものの":"V・い-വിശേഷണം plain + ものの / な-വിശേഷണം + なものの / N + であるものの","Vた + ものだ（অতীতের স্মৃতি）":"Vた + ものだ (ഭൂതകാല ഓർമ്മകൾ)","V・い-বিশেষণ plain + わけがない / な-বিশেষণ + なわけがない / N + のわけがない":"V・い-വിശേഷണം plain + わけがない / な-വിശേഷണം + なわけがない / N + のわけがない","Vた + 上[うえ]で（ক্রম） / Vる・Nの + 上[うえ]で（ক্ষেত্র）":"Vた + 上[うえ]で (ക്രമം) / Vる・Nの + 上[うえ]で (വശം)","N + に対[たい]して / N + に対[たい]する + N（লক্ষ্য）":"N + に対[たい]して / N + に対[たい]する + N (ലക്ഷ്യം)"},"lessons.meaning_bn":{"… করা মাত্রই হঠাৎ":"ചെയ്ത ഉടൻ... പെട്ടെന്ന്","একদিকে …, অন্যদিকে …":"ഒരു വശത്ത് ..., മറുവശത്ത് ...","…এর তুলনায়":"...നെ അപേക്ഷിച്ച്","যদিও …, তবু …":"എങ്കിലും ..., എന്നിട്ടും ...","…কে সূচনা বা উপলক্ষ করে":"...നെ ഒരു തുടക്കമോ അവസരമോ ആക്കി","…অনুযায়ী মানিয়ে":"...അനുസരിച്ച്","…জুড়ে বিস্তৃতভাবে":"...നുടനീളം വ്യാപിച്ച് / ...കുറുകെ","… বলতে কী বোঝায়":"... കൊണ്ട് എന്താണ് അർത്ഥമാക്കുന്നത്","… না করেই":"... ചെയ്യാതെ","… বলার চেয়ে বরং …":"... എന്ന് പറയുന്നതിനേക്കാൾ","একেবারে … নয়, তা নয় / কিছুটা সম্ভব":"അത് ഒട്ടും ... അല്ല / അല്പം സാധ്യമാണ്","… নির্বিশেষে":"... പരിഗണിക്കാതെ","…কে ভিত্তি করে":"...നെ അടിസ്ഥാനമാക്കി / ...അനുസരിച്ച്","… হলেই সঙ্গে সঙ্গে / …এর ওপর নির্ভর":"... ഉടൻ തന്നെ / ...നെ ആശ്രയിച്ച്","… না করে উপায় নেই":"... ചെയ്യുകയല്ലാതെ മറ്റൊരു വഴിയുമില്ല","…এর প্রতি / এর বিপরীতে":"...നോട് / ...ന് വിപരീതമായി","নিশ্চয়ই … হবে, আমার দৃঢ় ধারণা":"തീർച്ചയായും ... സംഭവിക്കും, എനിക്ക് ഉറച്ച ബോധ്യമുണ്ട്","… হওয়ার কোনো কথাই নয়":"... ആകാൻ ഒരു വഴിയുമില്ല / ... എന്നത് ചോദ്യത്തിനപ്പുറമാണ്","ঠিক … বলেই":"കൃത്യമായി ... ആയതുകൊണ്ട് തന്നെ","… হলো মনে হতেই আবার …":"... ആണെന്ന് തോന്നിയ ഉടൻ...","…এর সঙ্গে সংশ্লিষ্ট পরিবর্তনে":"...മായി ബന്ധപ്പെട്ട മാറ്റങ്ങളുമായി ബന്ധപ്പെട്ട്","এমন বলা গেলেও":"അങ്ങനെ പറയാമെങ്കിലും...","… করার পরে / … করার ক্ষেত্রে":"... ചെയ്ത ശേഷം / ... ചെയ്യുന്ന സന്ദർഭത്തിൽ","যতক্ষণ … শর্ত বজায় থাকে":"... എന്ന ഷർത്ത് നിലനിൽക്കുന്നിടത്തോളം","একসময় প্রায়ই … করতাম":"മുൻകാലങ്ങളിൽ പലപ്പോഴും ... ചെയ്യാറുണ്ടായിരുന്നു","…এর মাধ্যমে / …জুড়ে":"...ലൂടെ / ...നുടനീളം","… হলেও / এমনকি … ক্ষেত্রেও":"... എങ്കിലും / ...ന്റെ സന്ദർഭത്തിൽ പോലും","যত …, তত পরিবর্তন":"കൂടുതൽ ..., കൂടുതൽ അത് മാറുന്നു","… না করে থাকতে পারি না":"... ചെയ്യാതിരിക്കാൻ കഴിയില്ല","পরিস্থিতিগত কারণে … করা চলে না":"സാഹചര്യങ്ങൾ കാരണം ... ചെയ്യാൻ കഴിയില്ല","অন্য কিছু নয়, ঠিক …ই":"... അല്ലാതെ മറ്റൊന്നുമല്ല / അത് ... തന്നെയാണ്","মাত্র …, এর বেশি নয়":"വെറും ..., അതിൽ കൂടുതലൊന്നുമില്ല","শুধু … নয়, অন্যদের ক্ষেত্রেও":"... മാത്രമല്ല, മറ്റുള്ളവർക്കും","খারাপ কিছু ঘটার আশঙ্কা আছে":"എന്തെങ്കിലും മോശം സംഭവിക്കുമെന്ന ഭയമുണ്ട്","সবসময় বা সবার ক্ষেত্রে … নয়":"എല്ലായ്പ്പോഴും അല്ലെങ്കിൽ എല്ലാ സന്ദർഭങ്ങളിലും ... അല്ല","মনে হয় যেন …":"അങ്ങനെയാണെന്ന് തോന്നുന്നു..."},"lessons.quiz.explanation_bn":{"必[かなら]ずしも + とは限[かぎ]らない সাধারণ অনুমানকে আংশিক নাকচ করে।":"必[かなら]ずしも + とは限[かぎ]らない ഒരു പൊതുവായ അനുമാനത്തെ ഭാഗികമായി നിഷേധിക്കുന്നു.","দুটি নেতিবাচক অংশ সীমিত বা শর্তসাপেক্ষ সক্ষমতা প্রকাশ করে।":"രണ്ട് നിഷേധ ഭാഗങ്ങൾ പരിമിതമായ അല്ലെങ്കിൽ ഷർത്തുള്ള കഴിവിനെ പ്രകടിപ്പിക്കുന്നു.","সংখ্যা কম বা সীমিত হিসেবে দেখাতে にすぎない।":"ഒരു സംഖ്യയെ ചെറുതോ പരിമിതമോ ആയി കാണിക്കാൻ にすぎない ഉപയോഗിക്കുക.","する-এর ব্যতিক্রমী ず-রূপ せず।":"せず എന്നത് する-ന്റെ ക്രമരഹിതമായ ず-രൂപമാണ്.","বিশ্রাম না নিয়ে কাজ চালানোর অর্থে dictionary form + ことなく।":"വിശ്രമം എടുക്കാതെ ജോലി തുടരുക എന്ന അർത്ഥത്തിൽ, dictionary form + ことなく.","ব্যবহারকারী বাড়ার সঙ্গে সম্পর্ক রেখে সেবা বেড়েছে।":"ഉപയോക്താക്കളുടെ എണ്ണം വർദ്ധിച്ചതിനനുസരിച്ച്, സേവനവും അതിനനുസരിച്ച് വികസിച്ചു.","ব্যর্থতা থেকে নতুন পড়ার পদ্ধতির শুরু হয়েছে।":"ഒരു പരാജയം പഠിക്കാനുള്ള പുതിയ വഴിയുടെ തുടക്കത്തിലേക്ക് നയിച്ചു.","অভিজ্ঞতা থাকুক বা না থাকুক আবেদন করা যাবে, তাই にかかわらず।":"നിങ്ങൾക്ക് അനുഭവം ഉണ്ടെങ്കിലും ഇല്ലെങ്കിലും അപേക്ഷിക്കാം, അതിനാൽ にかかわらず.","প্রথমে আলোচনা শেষ করে পরে সিদ্ধান্ত, তাই Vた + 上[うえ]で।":"ആദ്യം ചർച്ച പൂർത്തിയാക്കി പിന്നീട് തീരുമാനിക്കുക, അതിനാൽ Vた + 上[うえ]で.","নদীর পানি উপচে পড়া অনাকাঙ্ক্ষিত সম্ভাবনা, তাই おそれがある।":"നദി കരകവിയുന്നത് അഭികാമ്യമല്ലാത്ത ഒരു സാധ്യതയാണ്, അതിനാൽ おそれがある.","স্তরের সঙ্গে মিলিয়ে বই বদলায়, তাই に応[おう]じて।":"പുസ്തകം നിലവാരത്തിന് അനുയോജ്യമായി മാറുന്നു, അതിനാൽ に応[おう]じて.","উপভাষা কী, তার সংজ্ঞা দেওয়া হচ্ছে।":"ഒരു പ്രാദേശിക ഭാഷ എന്താണെന്നതിന്റെ നിർവചനം നൽകുന്നു.","বুকিং করার পরও প্রত্যাশিতভাবে যাওয়া হয়নি; ものの এই অমিল দেখায়।":"ബുക്കിംഗ് നടത്തിയ ശേഷവും, അവർ പ്രതീക്ഷിച്ചതുപോലെ പോയില്ല; ものの ഈ പൊരുത്തക്കേട് കാണിക്കുന്നു.","ব্যর্থ হওয়াটিকেই প্রস্তুতির গুরুত্ব বোঝার বিশেষ কারণ করা হয়েছে।":"പരാജയം തന്നെ തയ്യാറെടുപ്പിന്റെ പ്രാധാന്യം മനസ്സിലാക്കാനുള്ള പ്രത്യേക കാരണമാക്കുന്നു.","জানালা খোলার সঙ্গে সঙ্গে অপ্রত্যাশিত বাতাস—Vた + とたん।":"ജനൽ തുറന്ന നിമിഷം അപ്രതീക്ഷിതമായ ഒരു കാറ്റ് — Vた + とたん.","পরিশ্রমের ফলই আসল পরিচয়—এই জোরালো মূল্যায়নে にほかならない।":"കഠിനാധ്വാനത്തിന്റെ ഫലമാണ് ഒരാളുടെ യഥാർത്ഥ ഐഡന്റിറ്റി — ഈ ഊന്നിയ മൂല്യനിർണ്ണയത്തിന്, にほかならない.","する ব্যতিক্রমীভাবে せざるを得[え]ない হয়।":"する ക്രമരഹിതമായി せざるを得[え]ない ആയി മാറുന്നു.","কাজ ছিল সংস্কৃতি শেখার মাধ্যম, তাই を通[とお]して।":"ജോലി സംസ്കാരം പഠിക്കാനുള്ള മാർഗമായിരുന്നു, അതിനാൽ を通[とお]して.","শিক্ষার্থী ছাড়াও শিক্ষক অংশ নেন; সীমা বিস্তৃত হচ্ছে, তাই に限[かぎ]らず।":"വിദ്യാർത്ഥികൾ മാത്രമല്ല, അധ്യാപകരും പങ്കെടുക്കുന്നു; വ്യാപ്തി വികസിക്കുന്നു, അതിനാൽ に限[かぎ]らず.","終[お]わります থেকে ます বাদ দিয়ে 次第[しだい]; কাজ শেষ হলেই পরিকল্পিত যোগাযোগ।":"次第[しだい] ലഭിക്കാൻ 終[お]わります-ൽ നിന്ന് ます നീക്കം ചെയ്യുക; ജോലി പൂർത്തിയായ ഉടൻ ആസൂത്രിത ബന്ധം സംഭവിക്കുന്നു.","সস্তা হওয়া মেনেও কেনার সীমা দেখাচ্ছে।":"അത് വിലകുറഞ്ഞതാണെന്ന് അംഗീകരിക്കുമ്പോഴും, വാങ്ങുന്നതിന് ഒരു പരിധി അത് കാണിക്കുന്നു.","ব্যাখ্যার ভিত্তি হবে ঘটনা বা তথ্য, তাই に基[もと]づいて।":"വിശദീകരണം സംഭവങ്ങളെയോ വസ്തുതകളെയോ അടിസ്ഥാനമാക്കിയുള്ളതായിരിക്കും, അതിനാൽ に基[もと]づいて.","ফিরে আসার পরপরই আবার বের হওয়া—দ্রুত অবস্থা বদলাচ্ছে।":"തിരിച്ചെത്തിയ ഉടൻ വീണ്ടും പുറത്തുപോകുന്നു — സാഹചര്യം വേഗത്തിൽ മാറുന്നു.","কথা বলার ধরনকে উপমা দিয়ে বর্ণনা করায় かのように।":"സംസാര രീതി ഒരു ഉപമ ഉപയോഗിച്ച് വിവരിക്കുന്നു, അതിനാൽ かのように.","関心[かんしん] বিশেষ্যকে বর্ণনা করছে, তাই に対[たい]する।":"ഇത് 関心[かんしん] എന്ന നാമത്തെ പരിഷ്കരിക്കുന്നു, അതിനാൽ に対[たい]する.","শান্ত হওয়া ও যাতায়াত অসুবিধা—দুটি ভিন্ন দিক, তাই 一方[いっぽう]で।":"ശാന്തമായിരിക്കുന്നതും അസൗകര്യപ്രദമായ ഗതാഗതവും — രണ്ട് വ്യത്യസ്ത വശങ്ങൾ, അതിനാൽ 一方[いっぽう]で.","অভিজ্ঞতা বাড়ার সঙ্গে আত্মবিশ্বাস বাড়ছে—পরিবর্তনের সহগতি।":"അനുഭവം വർദ്ധിക്കുന്നതിനനുസരിച്ച്, ആത്മവിശ്വാസവും വളരുന്നു — മാറ്റങ്ങൾ ഒരുമിച്ച് നീങ്ങുന്നു.","রাগের বর্ণনা বদলে বিপাকে পড়াকে বেশি যথাযথ বলা হচ্ছে।":"അതിനെ കോപമായി വിവരിക്കുന്നതിന് പകരം, കുഴപ്പത്തിലാണെന്ന് വിവരിക്കുന്നതാണ് കൂടുതൽ കൃത്യമെന്ന് പറയുന്നു.","এখানে বসবাসের শর্ত বজায় থাকাকালীন নিয়ম মানতে হবে।":"ഇവിടെ, ഇവിടെ താമസിക്കുന്ന അവസ്ഥ തുടരുന്നിടത്തോളം നിയമങ്ങൾ പാലിക്കണം.","ব্যস্ততা মেনেও যোগাযোগের প্রয়োজন বোঝানো হয়েছে।":"തിരക്കുള്ളതായി അംഗീകരിക്കുമ്പോഴും, ബന്ധം ആവശ്യമാണെന്ന് അത് അറിയിക്കുന്നു.","দুই সপ্তাহজুড়ে সাক্ষাৎকার নেওয়ার বিস্তার বোঝাচ্ছে।":"രണ്ട് ആഴ്ച കാലയളവിൽ അഭിമുഖങ്ങൾ നടക്കുന്നുവെന്ന് ഇത് സൂചിപ്പിക്കുന്നു.","আলো জ্বলছে দেখে কেউ আছেন বলে দৃঢ় অনুমান করা হয়েছে।":"വെളിച്ചം കത്തുന്നത് കണ്ട്, ആരെങ്കിലും അവിടെ ഉണ്ടെന്ന് ഉറച്ച് അനുമാനിക്കുന്നു.","এটি দেরি করার সামর্থ্যের প্রশ্ন নয়; গুরুত্বপূর্ণ সভায় দেরি করা চলে না।":"ഇത് വൈകാൻ കഴിയുമോ എന്ന ചോദ്യമല്ല; ഒരു പ്രധാന യോഗത്തിന് ഒരാൾ വൈകരുത്.","গত মাস হচ্ছে তুলনার ভিত্তিকাল, তাই に比[くら]べて।":"കഴിഞ്ഞ മാസമാണ് താരതമ്യത്തിനുള്ള അടിസ്ഥാന കാലയളവ്, അതിനാൽ に比[くら]べて.","অতীতের পুনরাবৃত্ত অভ্যাস স্মরণ করতে Vた + ものだ।":"ഭൂതകാലത്തെ ആവർത്തിച്ചുള്ള ഒരു ശീലം ഓർമ്മിക്കാൻ, Vた + ものだ.","কোনোভাবেই বলার কথা নয়—দৃঢ় অস্বীকারে わけがない।":"അദ്ദേഹം അങ്ങനെ പറയാൻ ഒരു വഴിയുമില്ല — ഉറച്ച നിഷേധത്തിന്, わけがない."},"lessons.quiz.options":{"পড়তে একেবারে পারি না, তা নয়":"എനിക്ക് ഒട്ടും വായിക്കാൻ കഴിയില്ലെന്നല്ല","একেবারেই পড়তে পারি না":"എനിക്ക് ഒട്ടും വായിക്കാൻ കഴിയില്ല","অবশ্যই নিখুঁতভাবে পড়ি":"ഞാൻ തീർച്ചയായും കൃത്യമായി വായിക്കുന്നു"},"lessons.quiz.prompt":{"দৃঢ় অস্বীকার:「彼[かれ]がそんなことを言[い]う（　）。」":"ഉറച്ച നിഷേധം: 「彼[かれ]がそんなことを言[い]う（　）。」","「読[よ]めないことはない。」—কোন অর্থ?":"「読[よ]めないことはない。」 — എന്താണ് ഇതിനർത്ഥം?","「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」—সময়ের বিস্তার।":"「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」 — സമയ ദൈർഘ്യം.","する-এর সঠিক রূপ:「心配[しんぱい]（　）にはいられない。」":"する-ന്റെ ശരിയായ രൂപം: 「心配[しんぱい]（　）にはいられない。」","「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」—পরিবর্তনের সূচনা।":"「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」 — ഒരു മാറ്റത്തിന്റെ തുടക്കം.","「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」—মাধ্যম।":"「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」 — മാർഗം / മാധ്യമം.","「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」—দৃঢ় মূল্যায়ন।":"「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」 — ഊന്നിയ മൂല്യനിർണ്ണയം.","「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」—তুলনা।":"「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」 — താരതമ്യം.","দৃঢ় অনুমান:「電気[でんき]がついている。誰[だれ]かいる（　）。」":"ഉറച്ച അനുമാനം: 「電気[でんき]がついている。誰[だれ]かいる（　）。」","「すべて分[わ]かっている（　）話[はな]す。」—যেন সব জানে।":"「すべて分[わ]かっている（　）話[はな]す。」 — അദ്ദേഹത്തിന് എല്ലാം അറിയാമെന്നതുപോലെ.","「大雨[おおあめ]で川[かわ]があふれる（　）。」—অনাকাঙ্ক্ষিত ঝুঁকি।":"「大雨[おおあめ]で川[かわ]があふれる（　）。」 — അഭികാമ്യമല്ലാത്ത അപകടസാധ്യത.","「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」—শর্ত মেনে সীমা।":"「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」 — ഒരു ഷർത്ത് അംഗീകരിച്ച്, ഒരു പരിധി കാണിക്കുന്നു.","「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」—লক্ষ্যবিষয়।":"「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」 — ലക്ഷ്യ വിഷയം.","শেষ হলেই জানাব:「終[お]わり（　）、連絡[れんらく]します。」":"അത് പൂർത്തിയായ ഉടൻ ഞാൻ നിങ്ങളെ അറിയിക്കും: 「終[お]わり（　）、連絡[れんらく]します。」","「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」—ক্রমে পরিবর্তন।":"「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」 — ക്രമാനുഗതമായ മാറ്റം.","「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」—কারণে জোর।":"「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」 — കാരണത്തിന് ഊന്നൽ.","「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」—দুটি দিক।":"「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」 — രണ്ട് വശങ്ങൾ.","「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」—না করে।":"「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」 — ചെയ്യാതെ.","আগে আলোচনা, তারপর সিদ্ধান্ত:「相談[そうだん]（　）上[うえ]で、決[き]めます。」":"ആദ്യം ചർച്ച ചെയ്യുക, പിന്നീട് തീരുമാനിക്കുക: 「相談[そうだん]（　）上[うえ]で、決[き]めます。」","「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」—শিক্ষার্থীর বাইরেও প্রযোজ্য।":"「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」 — വിദ്യാർത്ഥികൾക്കപ്പുറവും ബാധകമാണ്.","「帰[かえ]ってきた（　）、また出[で]かけた。」—দ্রুত পালাবদল।":"「帰[かえ]ってきた（　）、また出[で]かけた。」 — വേഗത്തിലുള്ള തിരിച്ചുപോക്ക്.","する-এর সঠিক রূপ:「中止[ちゅうし]（　）を得[え]ない。」":"する-ന്റെ ശരിയായ രൂപം: 「中止[ちゅうし]（　）を得[え]ない。」","「レベル（　）、教材[きょうざい]を変[か]えます。」—মানিয়ে নেওয়া।":"「レベル（　）、教材[きょうざい]を変[か]えます。」 — പൊരുത്തപ്പെടൽ / ക്രമീകരണം.","সংজ্ঞা:「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」":"നിർവചനം: 「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」","「事実[じじつ]（　）、説明[せつめい]してください。」—ভিত্তি।":"「事実[じじつ]（　）、説明[せつめい]してください。」 — അടിസ്ഥാനം.","「怒[おこ]っている（　）、困[こま]っているようだ。」—আরও যথাযথ বর্ণনা।":"「怒[おこ]っている（　）、困[こま]っているようだ。」 — കൂടുതൽ കൃത്യമായ വിവരണം.","পুরোনো অভ্যাস:「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」":"പഴയ ശീലം: 「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」","「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」—দায়িত্ববোধ।":"「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」 — ഉത്തരവാദിത്തബോധം.","「参加者[さんかしゃ]は十人[じゅうにん]（　）。」—মাত্র দশজন।":"「参加者[さんかしゃ]は十人[じゅうにん]（　）。」 — പത്ത് പേർ മാത്രം."},"lessons.tip_bn":{"する-এর রূপ せざる; しざる নয়। নিজের আগ্রহে পছন্দ করা কাজের জন্য নয়।":"する-ന്റെ രൂപം せざる ആണ്; しざる അല്ല. സ്വന്തം താൽപ്പര്യപ്രകാരം തിരഞ്ഞെടുക്കുന്ന ജോലികൾക്കുള്ളതല്ല ഇത്.","わけではない = পুরোপুরি এমন নয়; わけがない = কোনোভাবেই এমন হওয়ার কথা নয়।":"わけではない = അങ്ങനെയായിരിക്കണമെന്നില്ല; わけがない = അങ്ങനെയാകാൻ ഒരു വഴിയുമില്ല.","এই পাঠে সংজ্ঞার ব্যবহার; とは思[おも]わなかった-তে বিস্ময়ের ব্যবহার আলাদা।":"ഈ പാഠത്തിൽ, നിർവചനങ്ങൾക്കുള്ള ഉപയോഗം; とは思[おも]わなかった-ൽ അത്ഭുതം പ്രകടിപ്പിക്കുന്ന ഉപയോഗം വ്യത്യസ്തമാണ്.","কারণ জানাতে からにほかならない; শুধু বিশেষ্যের পরিচয় জোর দিতে にほかならない।":"ഒരു കാരണം പറയാൻ からにほかならない ഉപയോഗിക്കുക; ഒരു നാമത്തിന്റെ ഐഡന്റിറ്റി മാത്രം ഊന്നിപ്പറയാൻ, にほかならない ഉപയോഗിക്കുക.","অভিজ্ঞতার মাধ্যমে শেখা এবং সারা বছরজুড়ে—এই দুই ব্যবহার প্রসঙ্গ দেখে আলাদা করুন।":"ഈ രണ്ട് ഉപയോഗങ്ങൾ തമ്മിൽ — അനുഭവത്തിലൂടെ പഠിക്കുന്നതും വർഷം മുഴുവനും — സന്ദർഭത്തെ അടിസ്ഥാനമാക്കി വേർതിരിക്കുക.","যদিও গ্রীষ্ম, তবু পাহাড়ে ঠান্ডা—এই ধরনের স্বীকারের পর সীমা দেখায়।":"വേനൽക്കാലമാണെങ്കിലും, മലകളിൽ തണുപ്പാണ് — അത്തരം ഒരു അംഗീകാരത്തിന് ശേഷമുള്ള പരിധികൾ കാണിക്കുന്നു.","だけでなく-এর মতো বিস্তার বোঝায়; “এই সময়ের মধ্যে সীমাবদ্ধ” অর্থের に限[かぎ]り আলাদা।":"だけでなく പോലെ, ഇത് വ്യാപനത്തെ സൂചിപ്പിക്കുന്നു; 'ഈ സമയത്തിനുള്ളിൽ പരിമിതം' എന്ന അർത്ഥത്തിലുള്ള に限[かぎ]り വ്യത്യസ്തമാണ്.","জোরপূর্বক বাইরের বাধ্যবাধকতা নয়; হাসি, চিন্তা, কান্নার মতো ভেতরের তাড়না প্রধান।":"ബാഹ്യമായ നിർബന്ധിത ബാധ്യതയല്ല; ചിരി, ചിന്തകൾ, കരച്ചിൽ പോലുള്ള ആന്തരിക പ്രേരണകളാണ് പ്രധാനം.","に応[おう]じて শর্ত অনুযায়ী বদলায়; にかかわらず শর্তে বদলায় না।":"に応[おう]じて സാഹചര്യങ്ങൾക്കനുസരിച്ച് മാറുന്നു; にかかわらず സാഹചര്യങ്ങളെ ആശ്രയിച്ച് മാറുന്നില്ല.","遅[おく]れるにしても মানে দেরি হলেও; দেরি করার অনুমতি দেওয়া নয়।":"遅[おく]れるにしても എന്നാൽ ഒരാൾ വൈകിയാലും എന്നാണ്; വൈകാൻ അനുമതി നൽകുന്നു എന്നല്ല.","দুটি ঘটনা শুধু পাশাপাশি নয়; সম্পর্কিত পরিবর্তন দেখাতে হবে।":"രണ്ട് സംഭവങ്ങളും വെറുതെ അടുത്തടുത്തല്ലെന്ന് കാണിക്കണം; അവ ബന്ധപ്പെട്ട മാറ്റങ്ങളാണ്.","食[た]べられないことはない = খাওয়া একেবারে অসম্ভব নয়; স্বচ্ছন্দে খেতে পারি এমন জোর নেই।":"食[た]べられないことはない = കഴിക്കുന്നത് പൂർണ്ണമായും അസാധ്യമല്ല; സുഖമായി കഴിക്കാൻ കഴിയുമെന്ന ശക്തമായ അർത്ഥമില്ല.","নিয়মিত “এর পরে” বলার জন্য てから যথেষ্ট; とたん হঠাৎ ঘটার অনুভূতি দেয়।":"സാധാരണ \"അതിനുശേഷം\" എന്നതിന്, てから മതി; とたん പെട്ടെന്ന് എന്തെങ്കിലും സംഭവിക്കുന്നതിന്റെ ഭാവം നൽകുന്നു.","কিসের সঙ্গে তুলনা করছেন তা পরিষ্কার রাখুন; শুধু সংখ্যা বললেই তুলনা সম্পূর্ণ হয় না।":"നിങ്ങൾ എന്തിനോടാണ് താരതമ്യം ചെയ്യുന്നതെന്ന് വ്യക്തമാക്കുക; വെറുതെ സംഖ്യകൾ പറയുന്നത് ഒരു താരതമ്യം പൂർത്തിയാക്കില്ല.","পরের বিশেষ্যকে বর্ণনা করলে かのようなN; ক্রিয়াকে বর্ণনা করলে かのようにV।":"തുടർന്നുള്ള ഒരു നാമത്തെ പരിഷ്കരിക്കുമ്പോൾ, かのようなN ഉപയോഗിക്കുക; ഒരു ക്രിയയെ പരിഷ്കരിക്കുമ്പോൾ, かのようにV ഉപയോഗിക്കുക.","রূপ বদলালে অর্থ বদলায়: 確認[かくにん]した上[うえ]で = যাচাইয়ের পরে; 働[はたら]く上[うえ]で = কাজ করার ক্ষেত্রে।":"രൂപം മാറുമ്പോൾ, അർത്ഥം മാറുന്നു: 確認[かくにん]した上[うえ]で = പരിശോധിച്ച ശേഷം; 働[はたら]く上[うえ]で = ജോലി ചെയ്യുമ്പോൾ / ജോലിയുടെ സന്ദർഭത്തിൽ.","মাত্র তিনজন = 三人[さんにん]にすぎない; প্রায় তিনজন = 三人[さんにん]ぐらい—অর্থ আলাদা।":"മൂന്ന് പേർ മാത്രം = 三人[さんにん]にすぎない; ഏകദേശം മൂന്ന് പേർ = 三人[さんにん]ぐらい — അർത്ഥങ്ങൾ വ്യത്യസ്തമാണ്.","আগের ঘটনাটি পরের পরিবর্তনের শুরু; দৈনন্দিন ছোট কারণেও সবসময় ব্যবহার করবেন না।":"മുൻ സംഭവം തുടർന്നുള്ള മാറ്റത്തിന്റെ തുടക്കമാണ്; എല്ലാ ചെറിയ ദൈനംദിന കാരണങ്ങൾക്കും ഇത് ഉപയോഗിക്കരുത്.","Vる + 一方[いっぽう]だ শুধু পরিবর্তন এক দিকেই এগোনো বোঝাতে পারে; এই পাঠে শেষে で আছে।":"Vる + 一方[いっぽう]だ എന്നാൽ ഒരു ദിശയിൽ പുരോഗമിക്കുന്ന ഒരു മാറ്റത്തെ ലളിതമായി സൂചിപ്പിക്കാം; ഈ പാഠത്തിൽ, അവസാനം で വരുന്നു.","বাক্যের পরের অংশে আগের শর্ত অনুযায়ী মানিয়ে নেওয়ার সম্পর্ক খুঁজুন।":"വാക്യത്തിന്റെ പിന്നീടുള്ള ഭാഗത്ത് മുൻ ഭാഗത്തെ സാഹചര്യത്തിനനുസരിച്ച് പൊരുത്തപ്പെടുന്ന ബന്ധം നോക്കുക.","から সাধারণ কারণ, からこそ সেই কারণকে জোর দেয়। পরে ইতিবাচক উপদেশ বা মূল্যায়ন প্রায়ই আসে।":"から ഒരു പൊതുവായ കാരണമാണ്, എന്നാൽ からこそ ആ കാരണത്തെ ഊന്നിപ്പറയുന്നു. പിന്നീട് പലപ്പോഴും ഒരു പോസിറ്റീവ് ഉപദേശമോ മൂല്യനിർണ്ണയമോ ഉണ്ടാകും.","নিশ্চয়তা অনুভব করলেও এটি অনুমান; হুবহু “প্রমাণিত সত্য” নয়।":"ശക്തമായ ഉറപ്പ് തോന്നിയാലും, ഇതൊരു ഊഹമാണ്; ഇത് കൃത്യമായ \"തെളിയിക്കപ്പെട്ട സത്യം\" അല്ല.","সাধারণ “ভাবছি” অর্থ নয়। দ্রুত পালাবদল; নিজের ইচ্ছাকৃত ধারাবাহিক কাজ বোঝাতে কম মানায়।":"\"ചിന്തിക്കുക\" എന്ന സാധാരണ അർത്ഥമല്ല. ദ്രുതഗതിയിലുള്ള ഒന്നിടവിട്ടുള്ള മാറ്റം; ഒരാളുടെ സ്വന്തം മനഃപൂർവ്വമായ തുടർച്ചയായ പ്രവൃത്തികൾ പ്രകടിപ്പിക്കാൻ അനുയോജ്യമല്ല.","সরাসরি dictionary form লাগে: 休[やす]むことなく; 休[やす]まないことなく লিখবেন না।":"dictionary form നേരിട്ട് ഉപയോഗിക്കുന്നു: 休[やす]むことなく; 休[やす]まないことなく എന്ന് എഴുതരുത്.","এই পাঠে শর্তের ব্যবহার। 時間[じかん]の限[かぎ]り মানে সময়ের শেষ সীমা পর্যন্ত—প্রসঙ্গ আলাদা।":"ഈ പാഠത്തിൽ, ഷർത്തുകൾക്കുള്ള ഉപയോഗം. 時間[じかん]の限[かぎ]り എന്നാൽ സമയത്തിന്റെ അവസാന പരിധി വരെ — സന്ദർഭം വ്യത്യസ്തമാണ്.","পরের অংশে পরিবর্তন দিন; একটি নির্দিষ্ট মুহূর্তের সিদ্ধান্ত বা সরাসরি আদেশ মানায় না।":"അടുത്ത ഭാഗത്ത്, ഒരു മാറ്റം നൽകുക; ഇത് ഒരു നിമിഷത്തെ തീരുമാനത്തിനോ നേരിട്ടുള്ള കല്പനയ്‌ക്കോ യോജിക്കുന്നില്ല.","終[お]わり次第[しだい] = শেষ হলেই; 天気[てんき]次第[しだい] = আবহাওয়ার ওপর নির্ভর।":"終[お]わり次第[しだい] = അത് അവസാനിച്ച ഉടൻ; 天気[てんき]次第[しだい] = കാലാവസ്ഥയെ ആശ്രയിച്ചിരിക്കുന്നു.","ভালো ফলের সম্ভাবনায় সাধারণত使[つか]わない; 危険[きけん] বা ক্ষতির পূর্বাভাসে মানায়।":"സാധാരണയായി ഒരു നല്ല ഫലത്തിന്റെ സാധ്യതയ്ക്ക് 使[つか]わない; 危険[きけん] അല്ലെങ്കിൽ നാശനഷ്ടം എന്നിവയുടെ പ്രവചനങ്ങൾക്ക് ഇത് അനുയോജ്യമാണ്.","একবারের সাম্প্রতিক ঘটনা নয়। ものだ-এর সাধারণ সত্য বা উপদেশের ব্যবহার থেকে এটি আলাদা।":"ഒറ്റത്തവണയുള്ള സമീപകാല സംഭവമല്ല. ものだ-യുടെ പൊതു സത്യം അല്ലെങ്കിൽ ഉപദേശ ഉപയോഗത്തിൽ നിന്ന് ഇത് വ്യത്യസ്തമാണ്.","সরাসরি অক্ষমতা できない থেকে আলাদা। 休[やす]まないわけにはいかない মানে বিশ্রাম নিতেই হবে।":"നേരിട്ടുള്ള കഴിവില്ലായ്മയായ できない-ൽ നിന്ന് വ്യത്യസ്തം. 休[やす]まないわけにはいかない എന്നാൽ ഒരാൾ വിശ്രമം എടുക്കണം എന്നാണ്.","একটি নির্দিষ্ট মুহূর্তের জন্য নয়। 一時間[いちじかん]にわたる説明[せつめい] মানে এক ঘণ্টাজুড়ে ব্যাখ্যা।":"ഇത് ഒരു പ്രത്യേക നിമിഷത്തിനുള്ളതല്ല. 一時間[いちじかん]にわたる説明[せつめい] എന്നാൽ ഒരു മണിക്കൂർ നീളുന്ന ഒരു വിശദീകരണം എന്നാണ്.","দুটি বিকল্পের মধ্যে দ্বিতীয়টি বেশি সঠিক—এই দিকটি খেয়াল রাখুন।":"രണ്ട് ബദലുകൾക്കിടയിൽ, രണ്ടാമത്തേത് കൂടുതൽ കൃത്യമാണെന്ന് ഓർമ്മിക്കുക.","পুরোপুরি অসম্ভব অর্থ নয়। 必[かなら]ずしも-এর সঙ্গে শেষে নেতিবাচক অর্থ রাখুন।":"ഇതിനർത്ഥം പൂർണ്ണമായും അസാധ്യമെന്നല്ല. 必[かなら]ずしも-യോടൊപ്പം അവസാനം ഒരു നിഷേധ അർത്ഥം നിലനിർത്തുക.","বিশেষ্যের আগে に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん]।":"ഒരു നാമത്തിന് മുമ്പ്, に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん].","単[たん]に “অনুযায়ী” নয়; সিদ্ধান্তের ভিত্তির সঙ্গে দৃঢ় সম্পর্ক আছে।":"ഇത് വെറും 単[たん]に 'അനുസരിച്ച്' എന്നല്ല; ഒരു തീരുമാനത്തിന്റെ അടിസ്ഥാനവുമായി ഇതിന് ശക്തമായ ബന്ധമുണ്ട്.","ものの-এর পরে বাস্তব ফল বা অবস্থা দিন। শুধু দুটি কাজের ক্রম বোঝাতে ব্যবহার করবেন না।":"ものの-ന് ശേഷം യഥാർത്ഥ ഫലമോ സാഹചര്യമോ നൽകുക. രണ്ട് പ്രവൃത്തികളുടെ കാലക്രമം കാണിക്കാൻ മാത്രം ഇത് ഉപയോഗിക്കരുത്."},"scope_bn":{"QUARTET II-এর ৭–১২ অধ্যায়ের থিম অনুসরণে নির্বাচিত ৩৬টি গ্রামারের নিজস্ব সহায়ক অনুশীলন। এটি মূল বইয়ের সম্পূর্ণ গ্রামার সূচি নয়।":"QUARTET II-ലെ അധ്യായം 7-12-ലെ വിഷയങ്ങളെ അടിസ്ഥാനമാക്കി തിരഞ്ഞെടുത്ത 36 വ്യാകരണ പോയിന്റുകൾക്കുള്ള സ്വന്തം സഹായ പരിശീലനം. ഇത് പ്രധാന പാഠപുസ്തകത്തിന്റെ പൂർണ്ണ വ്യാകരണ സൂചികയല്ല."},"study.dialogue":{"ঠিক বলেছেন। এখনই যোগাযোগ করে দেখব।":"നിങ്ങൾ പറഞ്ഞത് ശരിയാണ്. ഞാൻ അവരെ ഉടൻ ബന്ധപ്പെടും.","হ্যাঁ। যাচাই করার পরে সিদ্ধান্ত নিই।":"അതെ. പരിശോധിച്ച ശേഷം നമുക്ക് ഒരു തീരുമാനം എടുക്കാം.","নির্দেশনার কাগজ বাড়ালে কেমন হয়?":"നിർദ്ദേശ പേപ്പർ വർദ്ധിപ്പിച്ചാലോ?","আজ আপনার বাসায় আসতে পারি?":"ഇന്ന് എനിക്ക് നിങ്ങളുടെ വീട്ടിൽ വരാമോ?","কিছু হয়েছে?":"എന്തെങ്കിലും കുഴപ്പമുണ്ടോ?","গ্রাহকসেবার ক্ষেত্রে কোন বিষয়কে গুরুত্ব দেন?":"ഉപഭോക്തൃ സേവനത്തിൽ നിങ്ങൾ പ്രധാനമായി കരുതുന്നത് എന്താണ്?","আচ্ছা। তাহলে সুবিধামতো একটি দিন জানাবেন?":"മനസ്സിലായി. എന്നാൽ സൗകര്യപ്രദമായ ഒരു ദിവസം എന്നെ അറിയിക്കാമോ?","আগামীকাল একটু সাহায্য করবেন?":"നാളെ എന്നെ അല്പം സഹായിക്കാമോ?","আগে ব্যবহারকারীদের জিজ্ঞেস করে দেখব?":"ഞാൻ ഉപയോക്താക്കളോട് മുൻകൂട്ടി ചോദിക്കട്ടെ?","এই গ্রাফ থেকে কী বোঝা যায়?":"ഈ ഗ്രാഫിൽ നിന്ന് എന്ത് മനസ്സിലാക്കാം?","রবিবার হলে পারব।":"ഞായറാഴ്ചയാണെങ്കിൽ, എനിക്ക് അത് ചെയ്യാൻ കഴിയും.","এটিও একটি উপায়, তবে ভাষা বদলানোর প্রয়োজনও আছে বলে মনে করি।":"ഇതും ഒരു വഴിയാണ്, പക്ഷേ ഭാഷ മാറ്റേണ്ട ആവശ്യവുമുണ്ടെന്ന് ഞാൻ കരുതുന്നു.","তাহলে রবিবার হলে কেমন হয়?":"എന്നാൽ ഞായറാഴ്ചയായാലോ?","প্রথমে গ্রাহকের চাহিদা নিশ্চিত করি।":"ആദ്യം, ഞാൻ ഉപഭോക്താവിന്റെ ആവശ്യങ്ങൾ സ്ഥിരീകരിക്കുന്നു.","স্টেশনে খোঁজ নিয়ে দেখলে কেমন হয়?":"സ്റ്റേഷനിൽ പരിശോധിച്ചാലോ?","কিছু কথা জিজ্ঞেস করতে পারি?":"എനിക്ക് നിങ്ങളോട് കുറച്ച് കാര്യങ്ങൾ ചോദിക്കാമോ?","একটি গুরুত্বপূর্ণ খাতা হারিয়ে ফেলেছি।":"എനിക്ക് ഒരു പ്രധാന നോട്ട്ബുക്ക് നഷ്ടപ്പെട്ടു.","আগামীকাল কাজ আছে বলে পারব না।":"നാളെ എനിക്ക് ജോലിയുണ്ട്, അതിനാൽ എനിക്ക് കഴിയില്ല.","দুঃখিত, আজ আমার অন্য কাজ আছে।":"ക്ഷമിക്കണം, ഇന്ന് എനിക്ക് മറ്റ് കാര്യങ്ങൾ ചെയ്യാനുണ്ട്.","অন্য স্কুলেও কি একই রকম হবে?":"മറ്റ് സ്കൂളുകളിലും ഇത് ഇതുപോലെയാകുമോ?","ট্রেন ব্যবহারকারী সবচেয়ে বেশি।":"ട്രെയിൻ ഉപയോക്താക്കളാണ് ഏറ്റവും കൂടുതൽ.","জি, বলুন।":"അതെ, ദയവായി തുടരുക.","শনিবার বিকেল হলে ঠিক আছে।":"ശനിയാഴ്ച ഉച്ചകഴിഞ്ഞ് മതിയാകും.","শুধু এই জরিপ থেকে তা বিচার করা যায় না।":"ഈ സർവേയിൽ നിന്ന് മാത്രം അത് വിലയിരുത്താൻ കഴിയില്ല."},"study.kanji":{"বোঝা বা সমাধান":"മനസ്സിലാക്കൽ അല്ലെങ്കിൽ പരിഹാരം","তুলনা":"താരതമ്യം","দৃশ্য":"രംഗം","প্রত্যাশা":"പ്രതീക്ഷ","বৃদ্ধি":"വർദ്ധനവ്","মিলিত সহযোগিতা":"സംയുക്ത സഹകരണം","বাহিরে প্রকাশ":"ബാഹ്യ പ്രകടനം","অনুভূতি বা অবস্থা":"വികാരം അല്ലെങ്കിൽ അവസ്ഥ","অতিথি বা ক্রেতা":"അതിഥി അല്ലെങ്കിൽ ഉപഭോക്താവ്","অভ্যস্ত":"പരിചിതമായ","মনের ভাব":"മാനസികാവസ്ഥ","ধারণা বা চিন্তা":"ആശയം അല്ലെങ്കിൽ ചിന്ത","বদলানো":"മാറുന്നത്","বিবেচনা":"പരിഗണന","ভিন্ন":"വ്യത്യസ്തം","ভরসা":"ആശ്രയം","হ্রাস":"കുറവ്","রূপ বা ছাপ":"രൂപം അല്ലെങ്കിൽ മതിപ്പ്"},"study.listening_answer":{"এ সপ্তাহে প্রশ্ন তৈরি হবে; আগামী সপ্তাহে লাইব্রেরির প্রবেশপথে জরিপ হবে।":"ഈ ആഴ്ച ചോദ്യങ്ങൾ സൃഷ്ടിക്കും; അടുത്ത ആഴ്ച ലൈബ്രറി പ്രവേശന കവാടത്തിൽ സർവേ നടക്കും.","জীবনবৃত্তান্ত আনতে হবে; আগামী মঙ্গলবার বেলা ৩টার মধ্যে অফিসে আসতে হবে; পরিবর্তন চাইলে আগের দিনের মধ্যে ফোন করতে হবে।":"നിങ്ങൾ ഒരു റെസ്യൂമെ കൊണ്ടുവരണം; അടുത്ത ചൊവ്വാഴ്ച ഉച്ചകഴിഞ്ഞ് 3:00-നകം നിങ്ങൾ ഓഫീസിൽ എത്തണം; മാറ്റങ്ങൾ വരുത്തണമെങ്കിൽ, തലേദിവസത്തിനകം വിളിക്കണം.","শনিবার বেলা ২টা; স্টেশনের সামনের লাইব্রেরি; শুক্রবারের মধ্যে জানাতে হবে।":"ശനിയാഴ്ച ഉച്ചകഴിഞ്ഞ് 2:00; സ്റ്റേഷന് മുന്നിലുള്ള ലൈബ്രറി; വെള്ളിയാഴ്ചയ്ക്കകം മറുപടി നൽകണം.","মঙ্গলবার বিকেলে পারবেন; সময়সূচি বদলানো যাবে কি না যাচাই করতে বলছেন।":"ചൊവ്വാഴ്ച ഉച്ചകഴിഞ്ഞ് അവർക്ക് അത് ചെയ്യാൻ കഴിയും; ഷെഡ്യൂൾ മാറ്റാൻ കഴിയുമോ എന്ന് പരിശോധിക്കാൻ അവർ ആവശ്യപ്പെടുന്നു.","সকালে ৬÷১০ = ৬০ শতাংশ; নির্দিষ্ট সময় নেই একজনের। এগুলো অনুশীলনের সংখ্যা।":"രാവിലെ 6÷10 = 60 ശതമാനം; ഒരാൾക്ക് പ്രത്യേക സമയമില്ല. ഇവ പരിശീലന സംഖ്യകളാണ്.","গতকাল দোকানে যে আসনে বসেছিলেন সেখানে; আজ সন্ধ্যায় নিতে যাবেন।":"ഇന്നലെ നിങ്ങൾ കടയിൽ ഇരുന്ന സീറ്റിൽ; ഇന്ന് വൈകുന്നേരം നിങ്ങൾ അത് എടുക്കാൻ പോകും."},"study.listening_question":{"ব্যাগ কোথায় পাওয়া গেছে? বক্তা কখন নিতে যাবেন?":"ബാഗ് എവിടെയാണ് കണ്ടെത്തിയത്? സ്പീക്കർ എപ്പോഴാണ് അത് എടുക്കാൻ പോകുന്നത്?","কী আনতে হবে, কখন আসতে হবে, পরিবর্তন চাইলে কী করবেন?":"എന്ത് കൊണ്ടുവരണം, എപ്പോൾ വരണം, മാറ്റങ്ങൾ വരുത്തണമെങ്കിൽ എന്ത് ചെയ്യണം?","সকালে পড়ার অনুপাত কত? নির্দিষ্ট সময় নেই কতজনের?":"രാവിലെ പഠിക്കുന്നതിന്റെ അനുപാതം എന്താണ്? എത്ര പേർക്ക് പ്രത്യേക സമയമില്ല?","কখন, কোথায় এবং কত দিনের মধ্যে জানাতে হবে?":"എപ്പോൾ, എവിടെ, എപ്പോഴത്തേക്ക് ഞാൻ മറുപടി നൽകണം?","এ সপ্তাহে কী হবে? জরিপ কোথায় এবং কখন হবে?":"ഈ ആഴ്ച എന്ത് സംഭവിക്കും? സർവേ എവിടെ, എപ്പോൾ നടക്കും?","বক্তা কোন দিন পারবেন? শ্রোতার কাছে কী অনুরোধ করছেন?":"ഏത് ദിവസമാണ് സ്പീക്കർക്ക് അത് ചെയ്യാൻ കഴിയുക? ശ്രോതാവിനോട് അവർ എന്താണ് അഭ്യർത്ഥിക്കുന്നത്?"},"study.questions":{"সবার কাছে একই ব্যাখ্যা যথেষ্ট নয় কেন?":"എന്തുകൊണ്ടാണ് എല്ലാവർക്കും ഒരേ വിശദീകരണം മതിയാകാത്തത്?","মিনা যাওয়ার আগে কী করেনি?":"പുറപ്പെടുന്നതിന് മുമ്പ് മിന എന്താണ് ചെയ്യാതിരുന്നത്?","গ্রাহকের প্রয়োজন অনুযায়ী ব্যাখ্যা মানিয়ে নেওয়া।":"ഉപഭോക്താവിന്റെ ആവശ്യങ്ങൾക്ക് അനുയോജ്യമായ രീതിയിൽ വിശദീകരണങ്ങൾ പൊരുത്തപ്പെടുത്തുന്നു.","প্রথমবার আসা ব্যক্তির উদাহরণটি কী বোঝায়?":"ആദ്യമായി വരുന്ന ഒരു സന്ദർശകന്റെ ഉദാഹരണം എന്താണ് വ്യക്തമാക്കുന്നത്?","দৃষ্টিকোণ বদলানোর কারণ কী ছিল?":"വീക്ഷണം മാറ്റാനുള്ള കാരണം എന്തായിരുന്നു?","লেখাটির মূল শিক্ষা কী?":"പാഠത്തിന്റെ പ്രധാന പാഠം എന്താണ്?","পরের বাক্যে কাজ থাকার কারণ ও রবিবারের বিকল্প দেওয়ার তথ্য থেকে।":"അടുത്ത വാക്യത്തിൽ ജോലിയുണ്ടെന്ന വിവരത്തിൽ നിന്നും ഞായറാഴ്ച ഒരു ബദൽ വാഗ്ദാനം ചെയ്യുന്നതിൽ നിന്നും.","ট্রেন ব্যবহারকারীর অনুপাত কত এবং কীভাবে পেলেন?":"ട്രെയിൻ ഉപയോക്താക്കളുടെ അനുപാതം എന്താണ്, നിങ്ങൾക്ക് അത് എങ്ങനെ ലഭിച്ചു?","প্রথমে কাগজ বাড়াতে চেয়েছিল; পরে ব্যবহারকারীর প্রয়োজন বুঝে ভাষা সহজ করেছে।":"ആദ്യം, അവർ പേപ്പർ വർദ്ധിപ്പിക്കാൻ ആഗ്രഹിച്ചു; പിന്നീട്, ഉപയോക്താവിന്റെ ആവശ്യങ്ങൾ മനസ്സിലാക്കി, അവർ ഭാഷ ലളിതമാക്കി.","খাতা পাওয়া গেছে বলে স্টেশনের খবর আসার পর।":"നോട്ട്ബുക്ക് കണ്ടെത്തിയതായി സ്റ്റേഷനിൽ നിന്ന് വാർത്ത വന്നതിന് ശേഷം.","না; আগামীকাল পারবে না, রবিবার পারবে বলে বিকল্প দিয়েছে।":"ഇല്ല; അവർക്ക് നാളെ അത് ചെയ്യാൻ കഴിയില്ല, പക്ഷേ ഞായറാഴ്ച ചെയ്യാൻ കഴിയുമെന്ന് പറഞ്ഞ് അവർ ഒരു ബദൽ വാഗ്ദാനം ചെയ്തു.","ব্যবহারকারীদের সঙ্গে কথা বলে সমস্যাটি শ্রেণিবিভাগের নাম বুঝতে অসুবিধা বলে জানা যায়।":"ഉപയോക്താക്കളുമായി സംസാരിച്ചതിലൂടെ, വിഭാഗ നാമങ്ങൾ മനസ്സിലാക്കാനുള്ള ബുദ്ധിമുട്ടാണ് പ്രശ്നമെന്ന് മനസ്സിലായി.","আমন্ত্রণের ভাষা শুনে সময় ধরে না নিয়ে পরিস্থিতি যাচাই ও আলোচনা করা দরকার।":"ക്ഷണ ഭാഷയെ അടിസ്ഥാനമാക്കി അനുമാനിക്കുന്നതിന് പകരം, സാഹചര്യം പരിശോധിച്ച് ചർച്ച ചെയ്യേണ്ടത് ആവശ്യമാണ്.","১২÷২০×১০০ = ৬০ শতাংশ।":"12÷20×100 = 60 ശതമാനം.","কোন ঘটনায় ইউয়ের অনুভূতি বদলাল?":"ഏത് സംഭവമാണ് യുവിന്റെ വികാരങ്ങൾ മാറ്റിയത്?","প্রথম প্রস্তাব ও শেষ পদক্ষেপ কীভাবে আলাদা?":"ആദ്യ നിർദ്ദേശവും അവസാന ഘട്ടവും എങ്ങനെ വ്യത്യാസപ്പെട്ടിരിക്കുന്നു?","গ্রাহকের অভিজ্ঞতা ও চাহিদা আলাদা; সে অনুযায়ী ক্রম ও ভাষা বদলাতে হয়।":"ഉപഭോക്താക്കളുടെ അനുഭവങ്ങളും ആവശ്യങ്ങളും വ്യത്യാസപ്പെട്ടിരിക്കുന്നു; ക്രമവും ഭാഷയും അതിനനുസരിച്ച് ക്രമീകരിക്കണം.","না; খাতা হারিয়ে ইউয়ের অনুভূতির উপমা। かのように সূত্রটি দেখুন।":"ഇല്ല; നോട്ട്ബുക്ക് നഷ്ടപ്പെട്ടപ്പോൾ യുവിന്റെ വികാരങ്ങൾക്കുള്ള ഒരു ഉപമയാണിത്. かのように നിയമം കാണുക.","কথাগুলো মুছে যাওয়ার বর্ণনাটি কি বাস্তব ঘটনা?":"വാക്കുകൾ മാഞ്ഞുപോകുന്നതിന്റെ വിവരണം ഒരു യഥാർത്ഥ സംഭവമാണോ?","বন্ধুর সময় আছে কি না যোগাযোগ করে নিশ্চিত করেনি। দ্বিতীয় ও তৃতীয় বাক্য মিলিয়ে বুঝবেন।":"സുഹൃത്തിന് സമയമുണ്ടോ എന്ന് സ്ഥിരീകരിക്കാൻ അവൾ അവരെ ബന്ധപ്പെട്ടില്ല. രണ്ടാമത്തെയും മൂന്നാമത്തെയും വാക്യങ്ങൾ സംയോജിപ്പിച്ച് നിങ്ങൾക്ക് ഇത് മനസ്സിലാക്കാം.","難[むずか]しい-এর উদ্দেশ্য কোন তথ্য থেকে নিশ্চিত হলেন?":"ഏത് വിവരത്തിൽ നിന്നാണ് 難[むずか]しい എന്താണ് അർത്ഥമാക്കാൻ ഉദ്ദേശിച്ചതെന്ന് നിങ്ങൾ സ്ഥിരീകരിച്ചത്?","এই কথোপকথনে বন্ধু কি সাহায্য একেবারে অস্বীকার করেছে?":"ഈ സംഭാഷണത്തിൽ സുഹൃത്ത് സഹായം പൂർണ്ണമായും നിരസിച്ചോ?","উত্তরদাতা কেবল একটি ক্লাসের ২০ জন; নমুনা জাতীয় প্রতিনিধিত্ব নিশ্চিত করে না।":"പ്രതികരിച്ചവർ ഒരൊറ്റ ക്ലാസിലെ 20 പേർ മാത്രമാണ്; സാമ്പിൾ ദേശീയ പ്രാതിനിധ്യം ഉറപ്പാക്കുന്നില്ല.","কেন সারা জাপানের বিষয়ে সিদ্ধান্ত নেওয়া যায় না?":"എന്തുകൊണ്ടാണ് ജപ്പാനെ മുഴുവനായും സംബന്ധിച്ച് തീരുമാനങ്ങൾ എടുക്കാൻ കഴിയാത്തത്?"},"study.reading":{"たとえば-এর উদাহরণ আগের মানিয়ে নেওয়ার বক্তব্যকে স্পষ্ট করে।":"たとえば-യുടെ ഉദാഹരണം പൊരുത്തപ്പെടുത്തലിനെക്കുറിച്ചുള്ള മുൻ പ്രസ്താവന വ്യക്തമാക്കുന്നു.","পরের কারণ ও বিকল্প দিন থেকে আগের কথার উদ্দেশ্য পরিষ্কার হয়।":"തുടർന്നുള്ള കാരണത്തിൽ നിന്നും ബദൽ ദിവസത്തിൽ നിന്നും മുൻ പരാമർശത്തിന്റെ ഉദ്ദേശ്യം വ്യക്തമാകുന്നു.","অন্য দৃষ্টিকোণ থেকে ভাবাই উন্নতির সূচনা হলো।":"മറ്റൊരു വീക്ഷണകോണിൽ നിന്ന് ചിന്തിക്കുന്നതാണ് മെച്ചപ്പെടുത്തലിന്റെ തുടക്കം.","একটি ছোট দোকানের ম্যানেজারকে জিজ্ঞেস করলাম, কাজের কোন বিষয়টিকে গুরুত্ব দেন।":"ഒരു ചെറിയ കടയുടെ മാനേജരോട് അവരുടെ ജോലിയിൽ അവർ പ്രധാനമായി കരുതുന്നത് എന്താണെന്ന് ഞാൻ ചോദിച്ചു.","কাগজ কম থাকা নয়, নামের অর্থ না বোঝা—সমস্যার ব্যাখ্যা বদলাল।":"ഇത് പേപ്പറുകൾ കുറവായിരിക്കുന്നതിനെക്കുറിച്ചല്ല, മറിച്ച് പേരുകളുടെ അർത്ഥം മനസ്സിലാക്കാത്തതിനെക്കുറിച്ചാണ് — പ്രശ്നത്തിന്റെ വിശദീകരണം മാറി.","এই বাক্য গল্পের মোড় বদলায়; আগের উদ্বেগের বিপরীতে ভালো খবর।":"ഈ വാക്യം കഥയുടെ ഗതി മാറ്റുന്നു; മുൻ ഉത്കണ്ഠയുടെ പശ്ചാത്തലത്തിലുള്ള നല്ല വാർത്ത.","সমাধান হিসেবে আলোচনা এসেছে; কোনো দেশের সব মানুষকে নিয়ে নিয়ম বলা হয়নি।":"ഒരു പരിഹാരമായി ചർച്ച ഉയർന്നുവന്നു; ഒരു പ്രത്യേക രാജ്യത്തെ എല്ലാ ആളുകളെക്കുറിച്ചും ഒരു നിയമവും പറഞ്ഞിട്ടില്ല.","শেষ বাক্য ঘটনাটির সাধারণ শিক্ষা; উদাহরণের বাইরে অতিরিক্ত ফল দাবি করা হয়নি।":"അവസാന വാക്യം സംഭവത്തിന്റെ പൊതുവായ പാഠമാണ്; ഉദാഹരണത്തിനപ്പുറം അധിക ഫലങ്ങളൊന്നും അവകാശപ്പെടുന്നില്ല.","ক্লাসের অনুশীলনের জন্য ধরে নিই, ২০ শিক্ষার্থীকে যাতায়াতের উপায় জিজ্ঞেস করা হলো।":"ക്ലാസ് പരിശീലനത്തിനായി, 20 വിദ്യാർത്ഥികളോട് അവരുടെ ഗതാഗത മാർഗത്തെക്കുറിച്ച് ചോദിച്ചതായി കരുതുക.","ম্যানেজার বললেন, “একই ব্যাখ্যা বারবার বলাই যথেষ্ট নয়।”":"മാനേജർ പറഞ്ഞു, \"ഒരേ കാര്യം വീണ്ടും വീണ്ടും വിശദീകരിക്കുന്നത് മതിയാകില്ല.\"","তার মনে হলো, যেন গুরুত্বপূর্ণ কথাগুলোও হারিয়ে গেছে।":"പ്രധാനപ്പെട്ട വാക്കുകൾ പോലും നഷ്ടപ്പെട്ടതായി അദ്ദേഹത്തിന് തോന്നി.","しかし আগের প্রত্যাশার সঙ্গে বাস্তব অবস্থার অমিল আনে।":"しかし മുൻ പ്രതീക്ഷയും യഥാർത്ഥ സാഹചര്യവും തമ്മിലുള്ള പൊരുത്തക്കേട് അവതരിപ്പിക്കുന്നു.","এই দৃশ্যে কী বোঝায় বলা হয়েছে; সব ক্ষেত্রে একই অর্থ দাবি করা হয়নি।":"ഈ രംഗം എന്താണ് സൂചിപ്പിക്കുന്നതെന്ന് വിശദീകരിക്കുന്നു; എല്ലാ സന്ദർഭങ്ങൾക്കും ഒരേ അർത്ഥം അവകാശപ്പെടുന്നില്ല.","খাতাটি হাতে পেয়ে ইউ না হেসে থাকতে পারল না।":"നോട്ട്ബുക്ക് കയ്യിൽ ലഭിച്ചപ്പോൾ, യുവിന് ചിരിക്കാതിരിക്കാൻ കഴിഞ്ഞില്ല.","পরদিন স্টেশন থেকে জানানো হলো খাতাটি পাওয়া গেছে।":"അടുത്ത ദിവസം, നോട്ട്ബുക്ക് കണ്ടെത്തിയതായി സ്റ്റേഷൻ അറിയിച്ചു.","দুজন সময়সূচি নিশ্চিত করার গুরুত্ব নিয়ে আলোচনা করল।":"ഷെഡ്യൂളുകൾ സ്ഥിരീകരിക്കുന്നതിന്റെ പ്രാധാന്യത്തെക്കുറിച്ച് ഇരുവരും ചർച്ച ചെയ്തു.","কিন্তু বন্ধু তখন কাজে বের হওয়ার ঠিক আগের অবস্থায় ছিল।":"എന്നിരുന്നാലും, സുഹൃത്ത് ആ സമയത്ത് ജോലിക്ക് പോകാൻ തുടങ്ങുകയായിരുന്നു.","তারপর বলল, “কাজ আছে, তবে রবিবার হলে সাহায্য করতে পারব।”":"പിന്നീട് അദ്ദേഹം പറഞ്ഞു, \"എനിക്ക് ജോലിയുണ്ട്, പക്ഷേ ഞായറാഴ്ചയാണെങ്കിൽ എനിക്ക് സഹായിക്കാൻ കഴിയും.\"","এটি অনুশীলনের কাল্পনিক জরিপ; বাস্তব গবেষণা নয়।":"ഇത് പരിശീലനത്തിനുള്ള ഒരു സാങ്കൽപ്പിക സർവേയാണ്; യഥാർത്ഥ ഗവേഷണമല്ല.","বন্ধু বলল, “আগামীকাল একটু কঠিন হবে।”":"സുഹൃത്ത് പറഞ്ഞു, \"നാളെ അല്പം ബുദ്ധിമുട്ടായിരിക്കും.\"","প্রথম বাক্যে সমস্যাটি এসেছে; খাতাটির দৈনন্দিন গুরুত্বও জানা গেল।":"പ്രശ്നം ആദ്യ വാക്യത്തിൽ ഉയർന്നുവന്നു; നോട്ട്ബുക്കിന്റെ ദൈനംദിന പ്രാധാന്യവും വെളിപ്പെട്ടു.","বাসায় পৌঁছানো মাত্র সে বিষয়টি টের পেল।":"വീട്ടിലെത്തിയ ഉടൻ അദ്ദേഹം കാര്യം മനസ്സിലാക്കി.","অনুরোধের বিষয় ও সময় আগে দেওয়া হয়েছে।":"അഭ്യർത്ഥനയുടെ വിഷയവും സമയവും മുൻകൂട്ടി നൽകിയിരുന്നു.","পরদিন সে কোনো যোগাযোগ না করেই বন্ধুর বাসায় গেল।":"അടുത്ത ദിവസം, അവൾ യാതൊരു ബന്ധവുമില്ലാതെ സുഹൃത്തിന്റെ വീട്ടിൽ പോയി.","しかし উপসংহারের সীমা নির্দেশ করে।":"しかし നിഗമനത്തിന്റെ പരിധിയെ സൂചിപ്പിക്കുന്നു.","মোট ১২+৫+৩=২০; গণনার ভিত্তি একই আছে।":"ആകെ 12+5+3=20; കണക്കുകൂട്ടലിന്റെ അടിസ്ഥാനം അതേപടി നിലനിൽക്കുന്നു.","শেষ বাক্য লেখার মূল শিক্ষা।":"അവസാന വാക്യം എഴുതുന്നതിന്റെ പ്രധാന പാഠം.","最初[さいしょ]は প্রথম প্রস্তাব চিহ্নিত করছে; এটি চূড়ান্ত সমাধান নয়।":"最初[さいしょ]は ആദ്യ നിർദ്ദേശത്തെ അടയാളപ്പെടുത്തുന്നു; ഇത് അന്തിമ പരിഹാരമല്ല.","প্রথমে নির্দেশনার কাগজ বাড়ানোর কথা ভাবা হলো।":"ആദ്യം, നിർദ്ദേശ പേപ്പറുകൾ വർദ്ധിപ്പിക്കുന്നതിനെക്കുറിച്ച് അവർ ആലോചിച്ചു.","এই অভিজ্ঞতার মাধ্যমে মিনা কথার পাশাপাশি পরিস্থিতিও যাচাই করতে শুরু করল।":"ഈ അനുഭവത്തിലൂടെ, സംഭാഷണത്തോടൊപ്പം സാഹചര്യവും പരിശോധിക്കാൻ മിന തുടങ്ങി.","কারণ লক্ষ্যগোষ্ঠী কেবল একটি ক্লাস।":"കാരണം ലക്ഷ്യമിടുന്ന വിഭാഗം ഒരൊറ്റ ക്ലാസ് മാത്രമാണ്.","১২ জন ট্রেন, ৫ জন সাইকেল এবং ৩ জন হেঁটে যাওয়ার কথা বলল।":"12 പേർ ട്രെയിൻ എന്നും, 5 പേർ സൈക്കിൾ എന്നും, 3 പേർ നടത്തം എന്നും പറഞ്ഞു.","かのように উপমা; বাস্তবে সব কথা মুছে গেছে এমন তথ্য নয়।":"かのように ഒരു ഉപമയാണ്; എല്ലാ വാക്കുകളും യഥാർത്ഥത്തിൽ മായ്ച്ചുകളഞ്ഞു എന്ന വസ്തുതയല്ല ഇത്.","聞[き]きました-র প্রশ্নবিষয় দিয়ে পরের উত্তরের কেন্দ্র নির্ধারিত হয়।":"聞[き]きました-ലെ ചോദ്യത്തിന്റെ വിഷയം തുടർന്നുള്ള ഉത്തരത്തിന്റെ കേന്ദ്രം നിർണ്ണയിക്കുന്നു.","ট্রেন ব্যবহারকারীর অনুপাত ৬০ শতাংশ।":"ട്രെയിൻ ഉപയോക്താക്കളുടെ അനുപാതം 60 ശതമാനമാണ്.","তাই কর্মীরা পরিচিত ভাষায় লেখা নির্দেশনা ব্যবহার করলেন।":"അതിനാൽ, പരിചിതമായ ഭാഷയിൽ എഴുതിയ നിർദ്ദേശങ്ങൾ ജീവനക്കാർ ഉപയോഗിച്ചു.","এখানে 難[むずか]しい কেবল কাজের জটিলতা নাও বোঝাতে পারে।":"ഇവിടെ, 難[むずか]しい എന്നാൽ ജോലിയുടെ സങ്കീർണ്ണത മാത്രമായിരിക്കണമെന്നില്ല.","を通[とお]して অভিজ্ঞতার মাধ্যমে শেখা; ようになった আচরণের পরিবর্তন।":"を通[とお]して എന്നാൽ അനുഭവത്തിലൂടെ പഠിക്കുക എന്നാണ്; ようになった എന്നാൽ പെരുമാറ്റത്തിലെ മാറ്റമാണ്.","に応[おう]じて মানিয়ে নেওয়া; そうです বক্তার কাছ থেকে শোনা তথ্য।":"に応[おう]じて എന്നാൽ പൊരുത്തപ്പെടുക എന്നാണ്; そうです എന്നാൽ മറ്റൊരാളിൽ നിന്ന് കേട്ട വിവരമാണ്.","たとたん পৌঁছানোর সঙ্গে হঠাৎ উপলব্ধি বোঝায়।":"たとたん എത്തിയപ്പോഴുള്ള പെട്ടെന്നുള്ള തിരിച്ചറിവിനെ സൂചിപ്പിക്കുന്നു.","গ্রাহকের চাহিদা অনুযায়ী তিনি ব্যাখ্যার ক্রম ও ভাষা বদলান।":"ഉപഭോക്താവിന്റെ ആവശ്യങ്ങൾക്കനുസരിച്ച് അദ്ദേഹം വിശദീകരണങ്ങളുടെ ക്രമവും ഭാഷയും മാറ്റുന്നു.","ことなく মানে না করে; মিনার আগেই খবর না দেওয়া এখানে গুরুত্বপূর্ণ।":"ことなく എന്നാൽ ചെയ്യാതെ എന്നാണ്; മിന മുൻകൂട്ടി അറിയിക്കാതിരുന്നത് ഇവിടെ പ്രധാനമാണ്.","কেন এক বন্ধুকে পরদিন বাসা বদলে সাহায্য করতে বলল।":"എന്തുകൊണ്ടാണ് ഒരു സുഹൃത്ത് അടുത്ത ദിവസം വീട് മാറാൻ സഹായിക്കാൻ മറ്റൊരാളോട് ആവശ്യപ്പെട്ടത്.","শেষ বাক্য প্রতিবেদকের উপলব্ধি; ম্যানেজারের সরাসরি উদ্ধৃতি নয়।":"അവസാന വാക്യം റിപ്പോർട്ടറുടെ തിരിച്ചറിവാണ്, മാനേജരുടെ നേരിട്ടുള്ള ഉദ്ധരണിയല്ല.","মনে হলো, মন দিয়ে অন্যের কথা শোনাই আস্থার শুরু।":"മറ്റുള്ളവരെ ശ്രദ്ധയോടെ ശ്രദ്ധിക്കുന്നത് വിശ്വാസത്തിന്റെ തുടക്കമാണെന്ന് തോന്നി.","শেষ প্রতিক্রিয়া থেকে স্বস্তি ও আনন্দ বোঝা যায়।":"അവസാന പ്രതികരണം ആശ്വാസവും സന്തോഷവും അറിയിക്കുന്നു.","প্রথম বাক্যে বলা তথ্যটি আমন্ত্রণের ভাষা; এখনো সময় নির্দিষ্ট হয়নি।":"ആദ്യ വാക്യത്തിൽ പറഞ്ഞ വിവരം ക്ഷണത്തിന്റെ ഭാഷയാണ്; സമയം ഇതുവരെ വ്യക്തമാക്കിയിട്ടില്ല.","কিন্তু ব্যবহারকারীদের সঙ্গে কথা বলে জানা গেল, শ্রেণিবিভাগের নাম বোঝা কঠিন।":"എന്നിരുന്നാലും, ഉപയോക്താക്കളുമായി സംസാരിച്ചതിന് ശേഷം, വിഭാഗ നാമങ്ങൾ മനസ്സിലാക്കാൻ പ്രയാസമാണെന്ന് കണ്ടെത്തി.","ইউ প্রতিদিন ব্যবহার করা খাতাটি ট্রেনে ফেলে এল।":"യുയി തന്റെ ദൈനംദിന ഉപയോഗ നോട്ട്ബുക്ക് ട്രെയിനിൽ ഉപേക്ഷിച്ചു.","だけでは十分[じゅうぶん]ではない সীমা দেখাচ্ছে; কোনো ব্যাখ্যাই প্রয়োজন নেই বলা হয়নি।":"だけでは十分[じゅうぶん]ではない ഒരു പരിധി കാണിക്കുന്നു; ഒരു വിശദീകരണവും ആവശ്യമില്ലെന്ന് അത് പറയുന്നില്ല.","এই পরিস্থিতিতে “কঠিন” কথাটি পরদিনের অনুরোধ প্রত্যাখ্যান করছে।":"ഈ സാഹചര്യത്തിൽ, \"ബുദ്ധിമുട്ടാണ്\" എന്ന വാക്ക് അടുത്ത ദിവസത്തെ അഭ്യർത്ഥനയുടെ നിരാകരണമാണ്.","অর্থ বুঝতে শব্দের পাশাপাশি প্রসঙ্গও জরুরি।":"അർത്ഥം മനസ്സിലാക്കാൻ, വാക്കുകൾ പോലെ തന്നെ സന്ദർഭവും പ്രധാനമാണ്.","そこで আগের তথ্যের ভিত্তিতে করা পদক্ষেপকে যুক্ত করছে।":"そこで മുൻ വിവരങ്ങളെ അടിസ്ഥാനമാക്കി എടുത്ത നടപടിയെ ബന്ധിപ്പിക്കുന്നു.","মিনাকে এক বন্ধু বলল, “আবার বেড়াতে এসো।”":"ഒരു സുഹൃത്ത് മിനയോട് പറഞ്ഞു, \"വീണ്ടും സന്ദർശിക്കാൻ വരൂ.\"","にすぎない পরিসরের সীমাবদ্ধতা দেখায়।":"にすぎない വ്യാപ്തിയുടെ പരിമിതി കാണിക്കുന്നു.","একটি লাইব্রেরিতে বই খুঁজতে বেশি সময় লাগে বলে মতামত এসেছিল।":"ഒരു ലൈബ്രറിയിൽ പുസ്തകങ്ങൾ കണ്ടെത്താൻ വളരെയധികം സമയമെടുക്കുന്നു എന്ന ഫീഡ്‌ബാക്ക് ലഭിച്ചു.","শুরুতে ব্যবহারকারীর সমস্যা তুলে ধরা হয়েছে।":"തുടക്കത്തിൽ, ഉപയോക്താവിന്റെ പ്രശ്നം എടുത്തുകാണിക്കുന്നു.","১২÷২০×১০০=৬০; শুধু সংখ্যা নয়, মোটের ভিত্তি দেখুন।":"12÷20×100=60; വെറും സംഖ്യകളല്ല, ആകെയുള്ളതിന്റെ അടിസ്ഥാനം നോക്കുക.","তবে শুধু এই ফল দিয়ে জাপানের সব শিক্ষার্থী সম্পর্কে বলা যায় না।":"എന്നിരുന്നാലും, ഈ ഫലത്തിൽ നിന്ന് മാത്രം, ജപ്പാനിലെ എല്ലാ വിദ്യാർത്ഥികളെക്കുറിച്ചും പറയാൻ കഴിയില്ല.","যেমন, প্রথমবার আসা ব্যক্তিকে ব্যবহারের পদ্ধতি দিয়ে বোঝানো শুরু করেন।":"ഉദാഹരണത്തിന്, ആദ്യമായി വരുന്ന ഒരു സന്ദർശകന്, അത് എങ്ങനെ ഉപയോഗിക്കണമെന്ന് കാണിച്ചുകൊണ്ട് അദ്ദേഹം വിശദീകരിക്കാൻ തുടങ്ങുന്നു."},"study.reading_title":{"“একটু কঠিন” কথাটির পর কী হলো":"\"അല്പം ബുദ്ധിമുട്ടാണ്\" — ആ വാക്കുകൾക്ക് ശേഷം എന്ത് സംഭവിച്ചു","সমস্যার বদলে প্রয়োজন থেকে ভাবা":"പ്രശ്നങ്ങൾക്ക് പകരം ആവശ്യങ്ങളിൽ നിന്ന് ചിന്തിക്കുന്നു","ভালো সেবা মানে একই উত্তর নয়":"നല്ല സേവനം എന്നാൽ ഒരേ ഉത്തരം എന്നല്ല","একটি আমন্ত্রণ, দুই রকম ধারণা":"ഒരു ക്ഷണം, രണ്ട് തരം മതിപ്പുകൾ","হারানো খাতার ছোট গল্প":"നഷ്ടപ്പെട്ട ഒരു നോട്ട്ബുക്കിന്റെ ചെറുകഥ","জরিপের সংখ্যা থেকে কতটুকু বলা যায়":"സർവേ സംഖ്യകളിൽ നിന്ന് എത്രമാത്രം പറയാൻ കഴിയും"},"study.strategy":{"শব্দের আক্ষরিক অর্থের পাশাপাশি কে, কাকে, কোন অনুরোধে বলছে তা দেখুন। পরোক্ষ কথাকে সবার জন্য স্থির নিয়ম হিসেবে ধরবেন না।":"വാക്കുകളുടെ അക്ഷരാർത്ഥത്തോടൊപ്പം, ആരാണ് സംസാരിക്കുന്നത്, ആരോട്, എന്ത് അഭ്യർത്ഥനയോടെ എന്നതും നോക്കുക. പരോക്ഷ സംസാരത്തെ എല്ലാവർക്കും ഒരു നിശ്ചിത നിയമമായി കരുതരുത്.","শিরোনাম ও ছোট উপশিরোনাম দেখে যুক্তির ধাপ ধরুন। দাবি, কারণ, উদাহরণ ও বিকল্পকে আলাদা করুন। মতের বিরোধিতা করলে কারণসহ বিকল্প দিন।":"ശീർഷകവും ഉപശീർഷകങ്ങളും നോക്കി വാദത്തിന്റെ ഘട്ടങ്ങൾ കണ്ടെത്തുക. അവകാശവാദങ്ങൾ, കാരണങ്ങൾ, ഉദാഹരണങ്ങൾ, ബദലുകൾ എന്നിവ വേർതിരിക്കുക. ഒരു അഭിപ്രായത്തെ എതിർക്കുകയാണെങ്കിൽ, കാരണങ്ങളോടെ ഒരു ബദൽ നൽകുക.","চরিত্রের অনুভূতি কোন ঘটনা বা শব্দে বদলেছে তা দেখুন। উপমাকে বাস্তব ঘটনা হিসেবে নেবেন না। পর্যালোচনায় নিজের মূল্যায়নের কারণ দিন।":"ഏത് സംഭവങ്ങളോ വാക്കുകളോ കഥാപാത്രങ്ങളുടെ വികാരങ്ങൾ മാറ്റിയെന്ന് നോക്കുക. ഉപമകളെ യഥാർത്ഥ സംഭവങ്ങളായി എടുക്കരുത്. അവലോകനത്തിൽ നിങ്ങളുടെ മൂല്യനിർണ്ണയങ്ങൾക്ക് കാരണങ്ങൾ നൽകുക.","প্রশ্নের উত্তরে বক্তা প্রথমে সিদ্ধান্ত বলেছেন, না উদাহরণ দিয়েছেন, তা ধরুন। উদাহরণ কোন মূল কথাকে বোঝাচ্ছে সেটি খুঁজুন।":"സ്പീക്കർ ആദ്യം തങ്ങളുടെ തീരുമാനം പറഞ്ഞോ അതോ ചോദ്യങ്ങൾക്ക് മറുപടിയായി ഉദാഹരണങ്ങൾ നൽകിയോ എന്ന് മനസ്സിലാക്കുക. ഉദാഹരണങ്ങൾ ഏത് പ്രധാന പോയിന്റാണ് വ്യക്തമാക്കുന്നതെന്ന് കണ്ടെത്തുക.","বাক্যে কর্তা বাদ গেলে আগের বাক্য ও কথোপকথনের প্রবাহ দেখুন। অনুমান আর স্পষ্টভাবে বলা তথ্য আলাদা রাখুন।":"ഒരു വാക്യത്തിൽ വിഷയം കാണുന്നില്ലെങ്കിൽ, മുൻ വാക്യത്തിന്റെയും സംഭാഷണത്തിന്റെയും ഒഴുക്ക് നോക്കുക. അനുമാനങ്ങളും വ്യക്തമായി പറഞ്ഞ വിവരങ്ങളും വേർതിരിച്ച് സൂക്ഷിക്കുക.","জরিপের লক্ষ্যগোষ্ঠী, মোট উত্তরদাতা, সময় ও শতাংশের ভিত্তি আগে পড়ুন। উদাহরণের সংখ্যাকে বাস্তব জরিপের ফল হিসেবে ব্যবহার করবেন না।":"സർവേയുടെ ലക്ഷ്യ വിഭാഗം, ആകെ പ്രതികരിച്ചവർ, സമയം, ശതമാനത്തിന്റെ അടിസ്ഥാനം എന്നിവ ആദ്യം വായിക്കുക. ഉദാഹരണ സംഖ്യകളെ യഥാർത്ഥ സർവേ ഫലങ്ങളായി ഉപയോഗിക്കരുത്."},"study.vocab":{"প্রকাশভঙ্গি":"പ്രകടനം","দৃষ্টিকোণ":"വീക്ഷണം","ভুল বোঝাবুঝি":"തെറ്റിദ്ധാരണ","অনুভূতি":"വികാരങ്ങൾ","আস্থা":"വിശ്വാസം","উদ্বেগ":"ഉത്കണ്ഠ","অভিজ্ঞতা":"അനുഭവം","লক্ষ্যগোষ্ঠী বা বিষয়":"ലക്ഷ്യ വിഭാഗം അല്ലെങ്കിൽ വിഷയം","জরিপ বা অনুসন্ধান":"സർവേ അല്ലെങ്കിൽ ഗവേഷണം","অনুপাত":"അനുപാതം","উদ্দেশ্য":"ഉദ്ദേശ്യം","অন্যের কথা বিবেচনা":"മറ്റുള്ളവരോടുള്ള പരിഗണന","প্রসঙ্গ":"സന്ദർഭം","ভূমিকা":"ആമുഖം","সংকোচ বা সংযম":"മടി അല്ലെങ്കിൽ സംയമനം","চিন্তার সূচনা বা ধারণা":"ചിന്തയുടെ തുടക്കം അല്ലെങ്കിൽ ആശയം","পারস্পরিক আদানপ্রদান":"പരസ്പര വിനിമയം","কৌশল বা বুদ্ধিদীপ্ত চেষ্টা":"തന്ത്രം അല്ലെങ്കിൽ സമർത്ഥമായ ശ്രമം","সহযোগিতা":"സഹകരണം","চাহিদা বা আশা":"ആവശ്യം അല്ലെങ്കിൽ പ്രതീക്ഷ","ভিন্ন সংস্কৃতি":"വ്യത്യസ്ത സംസ്കാരം","প্রস্তাব":"നിർദ്ദേശം","অভ্যাস বা রীতি":"ശീലം അല്ലെങ്കിൽ ആചാരം","স্বস্তি":"ആശ്വാസം","গ্রাহকসেবা":"ഉപഭോക്തൃ സേവനം","হ্রাস":"കുറവ്","মনের ওপর ছাপ":"മനസ്സിലുള്ള മതിപ്പ്","বৃদ্ধি":"വർദ്ധനവ്","তুলনা":"താരതമ്യം","গল্প বা আখ্যান":"കഥ അല്ലെങ്കിൽ ആഖ്യാനം","দৃশ্য বা পরিস্থিতি":"രംഗം അല്ലെങ്കിൽ സാഹചര്യം","যাচাই করা":"പരിശോധന","প্রত্যাখ্যান করা":"നിരസിക്കൽ","উন্নতি":"മെച്ചപ്പെടുത്തൽ","জানানো":"അറിയിക്കൽ"},"study.writing":{"আমি খাতা হারানো একজনের ছোট গল্প পড়েছি।":"നോട്ട്ബുക്ക് നഷ്ടപ്പെട്ട ഒരാളെക്കുറിച്ചുള്ള ഒരു ചെറുകഥ ഞാൻ വായിച്ചു.","ট্রেন ব্যবহারকারী ১২ জন, যা সবচেয়ে বড় অংশ।":"ട്രെയിൻ ഉപയോക്താക്കൾ 12 പേരാണ്, ഇത് ഏറ്റവും വലിയ വിഭാഗമാണ്.","কিন্তু বন্ধু ভেবেছিল এখনো আলোচনা দরকার।":"പക്ഷേ ചർച്ച ഇപ്പോഴും ആവശ്യമാണെന്ന് സുഹൃത്ത് കരുതി.","আমারও প্রিয় জিনিস হারানোর অভিজ্ঞতা আছে বলে অনুভূতিটি বুঝেছি।":"പ്രിയപ്പെട്ട ഒരു വസ്തു നഷ്ടപ്പെട്ട അനുഭവം എനിക്കുമുള്ളതിനാൽ ആ വികാരം ഞാൻ മനസ്സിലാക്കി.","অনুশীলনের জরিপে একটি ক্লাসের ২০ শিক্ষার্থীকে প্রশ্ন করা হয়েছে।":"പരിശീലന സർവേയിൽ, ഒരൊറ്റ ക്ലാസിലെ 20 വിദ്യാർത്ഥികളോട് ചോദിച്ചു.","এই অভিজ্ঞতার পর গুরুত্বপূর্ণ বিষয় স্পষ্টভাবে বলে নিশ্চিত করার চেষ্টা করি।":"ഈ അനുഭവത്തിന് ശേഷം, പ്രധാനപ്പെട്ട കാര്യങ്ങൾ വ്യക്തമായി പറയാനും സ്ഥിരീകരിക്കാനും ഞാൻ ശ്രമിക്കുന്നു.","মূল চরিত্রের উদ্বেগ পরিচিত ভাষায় তুলে ধরা হয়েছে।":"പ്രധാന കഥാപാത്രത്തിന്റെ ഉത്കണ്ഠ പരിചിതമായ ഭാഷയിൽ പ്രകടിപ്പിക്കുന്നു.","যেমন কঠিন শব্দ পরিচিত প্রকাশে বদলে দেওয়া যায়।":"ഉദാഹരണത്തിന്, ബുദ്ധിമുട്ടുള്ള വാക്കുകൾ പരിചിതമായ പ്രയോഗങ്ങളാക്കി മാറ്റാം.","তাই যারা ব্যবহার করবেন তাঁদের মতামত শোনা উচিত বলে মনে করি।":"അതിനാൽ, അത് ഉപയോഗിക്കുന്നവരുടെ അഭിപ്രായങ്ങൾ ഞങ്ങൾ ശ്രദ്ധിക്കണമെന്ന് ഞാൻ കരുതുന്നു.","এটি এমন গল্প যা দৈনন্দিন ছোট ঘটনাকেও গুরুত্ব দিতে শেখায়।":"ചെറിയ ദൈനംദിന സംഭവങ്ങളെപ്പോലും വിലമതിക്കാൻ നമ്മെ പഠിപ്പിക്കുന്ന ഒരു കഥയാണിത്.","আমি ভেবেছিলাম সময় ঠিক হয়ে গেছে।":"സമയം തീരുമാനിച്ചതായി ഞാൻ കരുതി.","সম্পর্ক ও পরিস্থিতি অনুযায়ী তা বদলায়।":"ബന്ധത്തിനും സാഹചര്യത്തിനും അനുസരിച്ച് അത് മാറുന്നു.","আমার মতে নির্দেশনা তৈরির সময় ব্যবহারকারীর দৃষ্টিকোণ জরুরি।":"എന്റെ അഭിപ്രായത്തിൽ, നിർദ്ദേശങ്ങൾ സൃഷ്ടിക്കുമ്പോൾ ഉപയോക്താവിന്റെ വീക്ഷണം അത്യാവശ്യമാണ്.","দীর্ঘ অভিজ্ঞতার ভিত্তিতে তিনি বোঝানোর ধরনে কৌশল ব্যবহার করেন।":"തന്റെ ദീർഘമായ അനുഭവത്തെ അടിസ്ഥാനമാക്കി, വിശദീകരിക്കുന്ന രീതിയിൽ അദ്ദേഹം തന്ത്രപരമായ സാങ്കേതിക വിദ്യകൾ ഉപയോഗിക്കുന്നു.","তাঁর মতে সবচেয়ে গুরুত্বপূর্ণ হলো গ্রাহকের কথা শোনা।":"അദ്ദേഹത്തിന്റെ അഭിപ്രായത്തിൽ, ഏറ്റവും പ്രധാനപ്പെട്ട കാര്യം ഉപഭോക്താവിനെ ശ്രദ്ധിക്കുക എന്നതാണ്.","আমি পাশের দোকানের ম্যানেজারের সাক্ষাৎকার নিয়েছি।":"അയൽപക്കത്തെ കടയുടെ മാനേജരെ ഞാൻ അഭിമുഖം നടത്തി.","জাপানিতে কোনো সময় না করার আগে কারণ বলা হয়।":"ജാപ്പനീസിൽ, നിരസിക്കുന്നതിന് മുമ്പ് ഒരു കാരണം പറയുന്നു.","না বুঝলে আমি ভদ্রভাবে নিশ্চিত হতে চাই।":"എനിക്ക് മനസ്സിലായില്ലെങ്കിൽ, മാന്യമായി ഉറപ്പുവരുത്താൻ ഞാൻ ആഗ്രഹിക്കുന്നു.","আমিও অন্যের অবস্থান বিবেচনা করে কাজ করতে চাই বলে মনে হয়েছে।":"മറ്റുള്ളവരുടെ വീക്ഷണങ്ങൾ പരിഗണിച്ചുകൊണ്ട് പ്രവർത്തിക്കാൻ ഞാനും ആഗ്രഹിക്കുന്നുവെന്ന് എനിക്ക് തോന്നി.","তবে সবসময় একই প্রকাশ ব্যবহার হয় না।":"എന്നിരുന്നാലും, കൃത്യമായി ഒരേ പ്രയോഗം എല്ലായ്പ്പോഴും ഉപയോഗിക്കാറില്ല.","জাপানে নতুন আসার সময় এক বন্ধুর সঙ্গে কথা দেওয়া নিয়ে সমস্যায় পড়েছিলাম।":"ഞാൻ ആദ്യമായി ജപ്പാനിൽ വന്നപ്പോൾ, ഒരു സുഹൃത്തുമായി വാഗ്ദാനം ചെയ്യുന്നതിൽ എനിക്ക് ബുദ്ധിമുട്ടുണ്ടായിരുന്നു.","সাইকেল ব্যবহারকারীর তুলনায় ৭ জন বেশি।":"സൈക്കിൾ ഉപയോക്താക്കളെ അപേക്ഷിച്ച് 7 പേർ കൂടുതൽ.","কারণ তথ্য বেশি হলেই অর্থ পরিষ্কার হয় এমন নয়।":"കാരണം കൂടുതൽ വിവരങ്ങൾ ഉണ്ടെന്നത് അർത്ഥം വ്യക്തമാണെന്ന് അർത്ഥമാക്കണമെന്നില്ല.","তবে অল্পসংখ্যক ব্যক্তির ফল বলে এটি সামগ্রিক প্রবণতা নাও হতে পারে।":"എന്നിരുന്നാലും, ഫലങ്ങൾ കുറച്ച് ആളുകളുടേതായതിനാൽ, ഇത് മൊത്തത്തിലുള്ള ഒരു പ്രവണത ആയിരിക്കണമെന്നില്ല."},"study.writing_prompt":{"নিজের একটি ভুল বোঝাবুঝির অভিজ্ঞতা লিখুন: ঘটনা → নিজের ধারণা → অন্য পক্ষের অবস্থা → পরেরবার কী করবেন।":"നിങ്ങളുടെ സ്വന്തം തെറ്റിദ്ധാരണയുടെ ഒരു അനുഭവത്തെക്കുറിച്ച് എഴുതുക: സംഭവം → നിങ്ങളുടെ അനുമാനം → മറുകക്ഷിയുടെ സാഹചര്യം → അടുത്ത തവണ നിങ്ങൾ എന്ത് ചെയ്യും.","বাংলা ও জাপানিতে কোনো অনুরোধ ফিরিয়ে দেওয়ার একটি করে উদাহরণ দিন। শব্দের অর্থ, সম্পর্ক ও পরিস্থিতি আলাদা করে লিখুন; জাতিগত সাধারণীকরণ এড়িয়ে চলুন।":"ബംഗാളിയിലും ജാപ്പനീസിലും ഒരു അഭ്യർത്ഥന നിരസിക്കുന്നതിന്റെ ഓരോ ഉദാഹരണം വീതം നൽകുക. വാക്കുകളുടെ അർത്ഥങ്ങൾ, ബന്ധങ്ങൾ, സാഹചര്യങ്ങൾ എന്നിവ പ്രത്യേകം എഴുതുക; വംശീയ പൊതുവൽക്കരണങ്ങൾ ഒഴിവാക്കുക.","একটি গল্প বা সিনেমার সংক্ষিপ্ত রিভিউ লিখুন: পরিচয় → একটি দৃশ্য → নিজের অনুভূতি → সুপারিশের কারণ। সমাপ্তির সব তথ্য বলে দেবেন না।":"ഒരു കഥയുടെയോ സിനിമയുടെയോ ഒരു ചെറിയ അവലോകനം എഴുതുക: ആമുഖം → ഒരു രംഗം → സ്വന്തം വികാരങ്ങൾ → ശുപാർശയുടെ കാരണം. അവസാനത്തെക്കുറിച്ചുള്ള എല്ലാ വിവരങ്ങളും വെളിപ്പെടുത്തരുത്.","এই কাল্পনিক সংখ্যাগুলো ব্যবহার করে চার বাক্যের প্রতিবেদন লিখুন। লক্ষ্যগোষ্ঠী → সবচেয়ে বড় অংশ → তুলনা → সিদ্ধান্তের সীমা।":"ഈ സാങ്കൽപ്പിക സംഖ്യകൾ ഉപയോഗിച്ച് നാല് വാക്യങ്ങളുള്ള ഒരു റിപ്പോർട്ട് എഴുതുക. ലക്ഷ്യമിടുന്ന പ്രേക്ഷകർ → ഏറ്റവും വലിയ വിഭാഗം → താരതമ്യം → നിഗമനത്തിന്റെ പരിമിതി.","একটি ছোট সমস্যা বেছে ১৮০–২৫০ জাপানি অক্ষরে মতামত লিখুন: দাবি → কারণ → উদাহরণ → সম্ভাব্য আপত্তি → বাস্তব প্রস্তাব।":"ഒരു ചെറിയ പ്രശ്നം തിരഞ്ഞെടുത്ത് 180-250 ജാപ്പനീസ് അക്ഷരങ്ങളിൽ ഒരു അഭിപ്രായം എഴുതുക: അവകാശവാദം → കാരണം → ഉദാഹരണം → സാധ്യമായ എതിർപ്പ് → പ്രായോഗിക നിർദ്ദേശം.","কোনো পরিচিত ব্যক্তির কাজ সম্পর্কে তিনটি প্রশ্ন করুন। সরাসরি উক্তি এবং নিজের উপলব্ধি আলাদা করে একটি ছোট প্রতিবেদন লিখুন।":"നിങ്ങൾക്ക് അറിയാവുന്ന ഒരാളുടെ ജോലിയെക്കുറിച്ച് മൂന്ന് ചോദ്യങ്ങൾ ചോദിക്കുക. നേരിട്ടുള്ള ഉദ്ധരണികൾ നിങ്ങളുടെ സ്വന്തം തിരിച്ചറിവുകളിൽ നിന്ന് വേർതിരിച്ച് ഒരു ചെറിയ റിപ്പോർട്ട് എഴുതുക."},"title":{"QUARTET II · বাংলা গ্রামার সহায়িকা":"QUARTET II · വ്യാകരണ ഗൈഡ്"}},"qa":{"attr.aside@aria-label":{"পাঠ নির্বাচন":"പാഠം തിരഞ്ഞെടുക്കൽ"},"attr.div@aria-label":{"পড়ার ধরন":"വായനാ രീതി"},"attr.input@aria-label":{"গ্রামার খুঁজুন":"വ്യാകരണം തിരയുക"},"attr.meta@description":{"QUARTET Ⅱ-এর অধ্যায় ৭–১২-এর থিমে নির্বাচিত ৩৬টি বিষয়ে নিজস্ব বাংলা ব্যাখ্যা, ফুরিগানাসহ উদাহরণ ও অনুশীলন।":"QUARTET Ⅱ-ലെ അധ്യായം 7-12-ലെ വിഷയങ്ങളെ അടിസ്ഥാനമാക്കി തിരഞ്ഞെടുത്ത 36 വിഷയങ്ങളിൽ സ്വന്തം മലയാള വിശദീകരണങ്ങൾ, ഫുരിഗാനയോടുകൂടിയ ഉദാഹരണങ്ങളും പരിശീലനവും."},"attr.nav@aria-label":{"এই অধ্যায়ের গ্রামার":"ഈ അധ്യായത്തിലെ വ്യാകരണം","QUARTET বই ও পড়ার ধরন":"QUARTET പുസ്തകങ്ങളും വായനാ തരങ്ങളും","পথ নির্দেশনা":"വഴികാട്ടൽ"},"attr.progress@aria-label":{"গ্রামার শেখার অগ্রগতি":"വ്യാകരണ പഠന പുരോഗതി"},"text.uncovered":{"পাঠ ও অনুশীলন খুলতে JavaScript চালু করুন।":"പാഠങ്ങളും പരിശീലനവും തുറക്കാൻ JavaScript പ്രവർത്തനക്ഷമമാക്കുക.","N2 Grammar পড়ুন":"N2 Grammar വായിക്കുക"}}};
